style.css:
@-moz-document domain("olx.pl"), domain("olx.ua"), domain("olx.ro"), domain("olx.pt"), domain("olx.bg"), domain("olx.kz"), domain("olx.uz") {
/* ============================================================
     OLX ships a Tailwind + design-token frontend. Most colors
     resolve from CSS custom properties on :root, so re-pointing
     those tokens flips the bulk of the UI. The remaining light
     surfaces are emotion (css-*) wrappers with literal hex values
     and hashed class names, so they are handled structurally from
     stable data-testid / id anchors.
     ============================================================ */

  :root {
    color-scheme: dark !important;

    /* ---- Surfaces ---- */
    --color-background-primary: #14181d !important;
    --colorsBackgroundPrimary: #14181d !important;
    --color-background-secondary: #1c2128 !important;
    --colorsBackgroundSecondary: #1c2128 !important;
    --color-background-elevated: #1c2128 !important;
    --colorsBackgroundElevated: #1c2128 !important;
    --color-background-inverse: #0d1117 !important;
    --colorsBackgroundInverse: #0d1117 !important;
    --color-background-disabled: #21262d !important;
    --colorsBackgroundDisabled: #21262d !important;
    --color-background-action-secondary: #21262d !important;
    --colorsBackgroundActionSecondary: #21262d !important;
    /* The PRIMARY action surface is OLX's near-black #02282c. It backs every
       Nexus `[data-button-variant="primary"]` fill (the shop-profile "Pokaż
       numer" CTA, gallery circle buttons) and sat at 1.14:1 on the page base.
       One step above action-secondary so the two emphasis tiers stay apart;
       its label token (`--colorsForegroundOnInverse`) is white. */
    --color-background-action-primary: #30363d !important;
    --colorsBackgroundActionPrimary: #30363d !important;
    --color-background-transparent: #14181d00 !important;
    --colorsBackgroundTransparent: #14181d00 !important;

    /* ---- Foreground / text ---- */
    --color-foreground-primary: #e6edf3 !important;
    --colorsForegroundPrimary: #e6edf3 !important;
    --color-foreground-secondary: #9aa6b0 !important;
    --colorsForegroundSecondary: #9aa6b0 !important;
    --color-foreground-placeholder: #7d8893 !important;
    --color-foreground-on-dark: #e6edf3 !important;

    /* The "action" foreground (#02282c) is OLX's near-black. It paints the
       Nexus design-system components: rating-histogram counts, chip labels,
       secondary/tertiary button labels, and every `fill="currentColor"` icon
       (favourite hearts, dropdown check marks, location pins, chevrons). It
       is NOT one of the tokens the theme originally remapped, so all of those
       rendered dark-on-dark. Disabled/accent/status foregrounds ship dark or
       low-contrast values for the same reason. `on-accent` stays dark: it is
       the label colour on the mint accent fill. */
    --color-foreground-action-primary: #c4cdd6 !important;
    --colorsForegroundActionPrimary: #c4cdd6 !important;
    --color-foreground-accent: #5fd0c6 !important;
    --colorsForegroundAccent: #5fd0c6 !important;
    --color-foreground-disabled: #6b7681 !important;
    --colorsForegroundDisabled: #6b7681 !important;
    --colorsForegroundPlaceholder: #7d8893 !important;
    --color-foreground-status-success: #57ccc4 !important;
    --colorsForegroundStatusSuccess: #57ccc4 !important;
    --color-foreground-status-warning: #d6a425 !important;
    --colorsForegroundStatusWarning: #d6a425 !important;
    --color-foreground-status-error: #f0795f !important;
    --colorsForegroundStatusError: #f0795f !important;

    /* ---- Borders ---- */
    --color-border-subtle: #2d333b !important;
    --colorsBorderSubtle: #2d333b !important;
    --color-border-primary: #2d333b !important;
    --colorsBorderPrimary: #2d333b !important;
    --color-border-strong: #454d57 !important;
    --colorsBorderStrong: #454d57 !important;
    --color-border-medium: #2d333b !important;
    --colorsBorderMedium: #2d333b !important;
    --color-border-focus: #1fcabf !important;
    --colorsBorderFocus: #1fcabf !important;
    --color-border-disabled: #2d333b !important;
    --colorsBorderDisabled: #2d333b !important;
    --color-border-status-error: #c2402b !important;
    --colorsBorderStatusError: #c2402b !important;
    /* The near-black #02282c that outlines every `secondary` and `circle`
       button variant and draws the `tertiary` variant's text underline
       (`.n-button-text-wrapper::after` fills from it). Left native it is
       invisible on dark, so those buttons lose their whole edge. */
    --color-border-action-primary: #8b949e !important;
    --colorsBorderActionPrimary: #8b949e !important;

    /* ---- OLX accent (raw #23E5DB mint) refined for dark ----
       Keep the recognizable OLX teal/mint identity but pull the
       saturation/lightness down a touch so it sits calmly on the
       near-black palette and dark text on it stays readable. */
    --color-background-accent: #1fcabf !important;
    --colorsBackgroundAccent: #1fcabf !important;
    --color-border-accent: #1fcabf !important;
    --colorsBorderAccent: #1fcabf !important;
    --color-background-accent-subtle: #103c3b !important;
    --colorsBackgroundAccentSubtle: #103c3b !important;
    /* Label ON the subtle-accent fill: OLX ships #085c5d, a dark teal picked
       for the pale #c8f8f6 original. It lands dark-on-dark once that fill
       becomes #103c3b, so lift it to the same family, light side. */
    --color-foreground-on-accent-subtle: #7ee0d6 !important;
    --colorsForegroundOnAccentSubtle: #7ee0d6 !important;

    /* ---- Status colors: keep semantic hue, settle onto dark ---- */
    --color-background-status-success: #1f6b54 !important;
    --colorsBackgroundStatusSuccess: #1f6b54 !important;
    --color-background-status-success-subtle: #102a23 !important;
    --colorsBackgroundStatusSuccessSubtle: #102a23 !important;
    --color-background-status-error: #c2402b !important;
    --colorsBackgroundStatusError: #c2402b !important;
    --color-background-status-error-subtle: #3a1b16 !important;
    --colorsBackgroundStatusErrorSubtle: #3a1b16 !important;
    --color-background-status-warning: #d6a425 !important;
    --colorsBackgroundStatusWarning: #d6a425 !important;
    --color-background-status-warning-subtle: #322a12 !important;
    --colorsBackgroundStatusWarningSubtle: #322a12 !important;
  }

  /* ---- Base page ---- */
  html, body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* `domain("olx.pl")` also matches every OLX subdomain, including the help
     centre at pomoc.olx.<tld> — a Salesforce Lightning community this theme
     does not cover. The base paint above turned its body dark while its own
     near-black article headings and paragraphs kept their light-page colours,
     so every help article rendered dark-on-dark. Salesforce roots every
     community page at <html class="slds-no-wcag">, which nothing on the OLX
     marketplace carries: hand that surface back rather than half-theme it. */
  html.slds-no-wcag,
  html.slds-no-wcag body {
    background-color: #ffffff !important;
    color: #181818 !important;
  }
  html.slds-no-wcag a:hover { color: #014486 !important; }

  /* ---- Soften every default light border into a dark hairline ---- */
  * { border-color: #2d333b !important; }

  /* OLX's icons are inline <svg>s whose paths are fill="currentColor", and the
     colour is set ON THE SVG by a per-deploy hashed emotion class holding the
     literal near-black #02282c — not by a design token and not by the icon's
     container. So every one of them (dropdown check marks, chevrons, the
     geolocation pin, the sort/list-view toggles, the category caret) rendered
     dark-on-dark even though its surrounding text was correctly light. Let the
     icon inherit the colour of the thing it belongs to; icons with explicit
     path fills (brand logos, country flags, illustrations, rating stars) are
     untouched because an explicit fill wins over currentColor. */
  #mainContent svg,
  #footerContent svg { color: inherit !important; }
  /* …except the rating stars, whose gold IS the artwork: they are currentColor
     glyphs too, so plain inheritance would grey them out. */
  #mainContent svg[data-testid="star-filled"],
  #mainContent svg[data-testid="star-half"] { color: #ffce32 !important; }
  /* …and the category tree's selected-branch tick, which OLX paints in the raw
     brand mint #23E5DB — the only accent in that panel and the whole "you are
     here" cue, since every row otherwise shares one grey. Plain inheritance
     hands it the row colour, so the selected row read exactly like the rest. */
  #mainContent svg[data-testid="dropdown-checkmark-icon"] { color: #1fcabf !important; }
  /* The seller-profile category tree ("Filtruj ogłoszenia" → Kategorie) marks
     each expandable branch with a [data-testid="dropdown-expand-button"] chevron
     whose colour is the literal near-black #02282c set on the button itself, NOT
     a token — the icon-inherit rule above hands the child <svg> that same
     near-black, so on the dark base the chevron sat at ~1.05:1 and vanished. The
     sibling dropdown-checkmark-icon reads the remapped secondary token and stays
     legible; only the expand chevron carries the raw literal. Lift the button so
     its inheriting svg reads as a neutral affordance. */
  [data-testid="dropdown-expand-button"] { color: #9aa6b0 !important; }
  /* Each category row in that tree ([data-testid="dropdown-item"]) shows its ad
     count in a gold #FFCE32 pill with near-black label — the category-tree
     equivalent of the offer badges. The badge is the count <span>, the only span
     preceded by a sibling span (the label is first, so `span + span` hits the
     count and never the label). Our broad seller-listing span-lift greyed that
     count to #9aa6b0, which on the gold pill drops to ~1.7:1 and the number is
     unreadable. Put the near-black label back so it reads on the gold. */
  #mainContent [data-testid="dropdown-checkmark"] span + span {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }

  /* Selected-tab underline. OLX draws it as an INSET box-shadow in the literal
     near-black #02282c (not a border, not a token), so on dark it disappears
     and the active tab is indistinguishable from the inactive ones. The search
     filters (Wszystkie / Firmowe / Prywatne) and the seller-profile tabs
     (Wszystkie ogłoszenia / Oceny) mark the selected tab with
     data-is-active="true"; login.olx.<tld> instead uses a roving tabindex where
     the SELECTED tab is the one carrying tabindex="-1". (aria-selected is NOT a
     tab hook here — the sort dropdown puts it on its options, which must stay
     underline-free.) Repaint the underline in the OLX accent and brighten the
     active label. */
  button[data-is-active="true"],
  [data-testid="tabs"] button[tabindex="-1"] {
    box-shadow: inset 0 -3px 0 0 #1fcabf !important;
  }
  button[data-is-active="true"],
  button[data-is-active="true"] span,
  [data-testid="tabs"] button[tabindex="-1"],
  [data-testid="tabs"] button[tabindex="-1"] span {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }

  /* Skip-navigation links ("Przejdź do głównej części / stopki") live at the
     top of the #hydrate-root shell and slide into view on keyboard focus. The
     link text carries the near-black #02282c -webkit-text-fill token, so it
     renders dark-on-dark and is unreadable when focused; the wrapping first-div
     container also ships a literal white background. Both skip hrefs are stable
     and there is exactly one skip-nav ListContainer (scoped to that first div so
     other ListContainers aren't touched): give the box an opaque dark surface
     and lift the link text to legible light, forcing -webkit-text-fill-color. */
  #hydrate-root > div:first-of-type,
  #hydrate-root > div:first-of-type [data-nx-name="ListContainer"] {
    background-color: #1c2128 !important;
  }
  #hydrate-root a[href="#mainContent"],
  #hydrate-root a[href="#footerContent"] {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }

  /* ============================================================
     Header / global nav (OLX dark-teal bar -> deep neutral dark)
     ============================================================ */
  header.app-header,
  header[class*="app-header"] {
    background-color: #0d1117 !important;
    border-bottom: 1px solid #2d333b !important;
  }
  header.app-header a,
  header[class*="app-header"] a,
  header.app-header button { color: #e6edf3 !important; }
  /* Every header control (Czat / Obserwowane / Powiadomienia / Dla biznesu) marks
     hover by dimming its white label to the disabled foreground — the bar's only
     pointer affordance. The lift above is `!important`, so it pinned the label and
     those controls stopped responding entirely; only the account link still dimmed
     (it reads a token instead), leaving the row half-dead. Dim them the way the site
     does. The accent "Dodaj ogłoszenie" pill has no native hover state and must keep
     its dark-on-mint label, so it is re-asserted with the header class in the
     selector to out-specify the rule above. */
  header.app-header a:hover,
  header[class*="app-header"] a:hover,
  header.app-header button:hover {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  header.app-header [data-testid="post-new-ad-button"]:hover,
  header.app-header [data-testid="post-new-ad-button"]:hover span,
  header.app-header [data-cy="post-new-ad-button"]:hover,
  header.app-header [data-cy="post-new-ad-button"]:hover span {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }

  /* Header language switcher (multi-language domains — olx.ua/.kz/.uz show
     "Укр | Рус", etc.). The CURRENT language is a non-clickable
     <span data-testid="lang-switcher-item-*"> that inherits the
     --color-foreground-disabled token, which the theme tunes to #6b7681 for
     dark-text-on-light-card contexts — on the dark header that drops to ~4.1:1,
     dimmer than every other header control and below AA. The switchable
     language is an <a> already lifted by the header-anchor rule. Lift the
     active-language span to a legible light grey (still a touch below the
     bright link, keeping the current-vs-switch distinction). */
  [data-testid="langswitcher"] span {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }

  /* The "post new ad" CTA reads as a white pill by default. Its inner
     <span> carries its own near-black -webkit-text-fill-color, so set
     BOTH on the wrapper and the span or the label stays invisible. */
  [data-testid="post-new-ad-button"],
  [data-cy="post-new-ad-button"] {
    background-color: #1fcabf !important;
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
    border-color: #1fcabf !important;
  }
  [data-testid="post-new-ad-button"] span,
  [data-cy="post-new-ad-button"] span {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }

  /* Notification + account dropdowns */
  [data-testid="notification-hub-dropdown"],
  [data-cy="notification-hub-wrapper"],
  [class*="menu-dropdown"],
  [role="menu"], [role="listbox"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  /* ============================================================
     Main page wrappers — flatten literal light backgrounds.

     OLX's content lives inside emotion (css-<hash>) shells whose
     class names change every deploy, so we never target those
     hashes. Instead we anchor on the STABLE page-shell ids
     (#hydrate-root / #mainContent / #footerContent /
     #searchmain-container) and neutralise EVERY descendant
     div/section/article/ul to transparent — that wipes the literal
     #F2F4F5 / #FFFFFF content bands regardless of how deep the
     hashed wrapper sits. The real cards then re-establish their own
     opaque dark surface below (data-testid anchored). The <img>
     element itself is left alone (its pixels aren't a CSS bg). */
  #hydrate-root,
  #mainContent,
  #footerContent,
  #searchmain-container,
  [data-testid="home-page"],
  [data-testid="listing-grid"],
  [data-testid="listing"],
  main, .listing-grid {
    background-color: #14181d !important;
  }
  /* Blanket light-shell neutraliser: anything structural under the
     stable page containers loses its hardcoded light background and
     shows the dark base. Cards re-opaque themselves afterwards. */
  #mainContent div, #mainContent section, #mainContent article, #mainContent ul,
  #footerContent div, #footerContent section,
  #searchmain-container div, #searchmain-container section, #searchmain-container article {
    background-color: transparent !important;
  }
  [data-testid="home-page"] div,
  [data-testid="home-page"] section,
  [data-testid="listing-grid"] > div {
    background-color: transparent !important;
  }
  /* The homepage/search "content sheet" #searchmain-container carries an
     INLINE `background:#F2F4F5 !important` (set so the page sits opaque over
     a takeover/skin wallpaper ad). Inline !important can't be beaten by any
     stylesheet rule, so the container itself stays light — and the blanket
     neutraliser turns its children transparent, letting that light band show
     through the entire category grid + promoted-listings area (headings and
     tile labels go light-on-light). Its DIRECT children have no inline style,
     so re-opaque them to the dark base here; anchored under #mainContent to
     out-specify the neutraliser. The real search field / promo tiles / cards
     re-establish their own elevated surface on top. */
  #mainContent #searchmain-container > div {
    background-color: #14181d !important;
  }

  /* ============================================================
     Floating surfaces — RE-OPAQUE over the neutraliser.

     The blanket `#mainContent div/section/article/ul {transparent}`
     rule above (specificity id+type, 0,1,1) also blanks the
     background off every interactive floating panel that lives
     inside #mainContent — the global search autocomplete, the
     filter flyouts (sort / category / price-range / multiselect)
     and any role=menu/listbox popover. Left alone they render fully
     SEE-THROUGH, so the listing grid + breadcrumbs scroll right
     through the open menu and it's unreadable. Re-establish a solid
     opaque dark surface on each, anchored on the STABLE flyout/menu
     testids + roles and scoped under #mainContent so the rule
     out-specifies the neutraliser (0,2,0 > 0,1,1). */
  #mainContent [data-testid="flyout-content"],
  #mainContent [data-testid="category-dropdown-list"],
  #mainContent [data-testid="search-autosuggession"],
  #mainContent [data-testid="search-autosuggession"] [role="listbox"],
  #mainContent [role="menu"],
  #mainContent [role="listbox"],
  #mainContent [class*="multi-select-body"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  /* ============================================================
     Search bar (white field on the hero) -> dark input
     ============================================================ */
  [data-testid="search-form"],
  [data-testid="search-autosuggession"],
  form[data-testid="search-form"] > div {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  [data-testid="search-input"],
  [data-cy="search-bar-input"],
  [data-testid="location-search-input"],
  [data-cy="location-search-input"],
  input[type="text"], input[type="search"], input[type="number"],
  input[type="email"], input[type="password"], input[type="tel"],
  textarea, select {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    /* OLX drives the RENDERED text of its select-look fields through
       -webkit-text-fill-color (the near-black #02282c), which overrides `color`
       — so the chosen value of every readonly "picker" input (the mobile filter
       form's Kategoria / Lokalizacja / Stan) painted near-black on the dark
       field and the current selection was invisible. Set both channels. */
    -webkit-text-fill-color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  ::placeholder { color: #7d8893 !important; opacity: 1 !important; }
  /* Nexus text fields draw the field surface on the WRAPPER and leave the <input>
     transparent — the same contract as the price-range fields further down. The
     generic rule above filled only the input, so each of these rendered two-tone: a
     lighter slab inset inside its own darker box, with the magnifier / chevron gutter
     left on the wrapper colour (the seller-profile "Znajdź na tej stronie" and Sortuj
     boxes, and the mobile filter form's Kategoria / Lokalizacja / Stan pickers). Hand
     the surface back to the wrapper. Ties the generic rule on specificity, so it has
     to stay after it. */
  input.n-textinput-input,
  [data-nx-name="NexusInputSearch"] input {
    background-color: transparent !important;
  }

  /* Nexus checkboxes ("tylko ze zdjęciem", "Tylko z przesyłką", the sign-up
     consents). The real <input> is visually replaced by a sibling
     .n-checkbox-icon-wrapper <div>, which draws the box: a 2px #02282c outline
     when unchecked, and the SAME near-black as a solid fill (plus a white tick)
     when checked. Two of our own rules gutted it — the blanket border reset
     dropped the outline to the #2d333b hairline (1.4:1 on the page base, below
     the 3:1 needed for a control boundary), and the structural
     `#mainContent div { background: transparent }` neutraliser wiped the checked
     fill, so checked and unchecked differ only by a faint tick. Restore a
     legible outline and give the checked state the OLX accent fill. */
  .n-checkbox-icon-wrapper { border-color: #6b7681 !important; }
  input[aria-checked="true"] + .n-checkbox-icon-wrapper,
  #mainContent input[aria-checked="true"] + .n-checkbox-icon-wrapper {
    background-color: #1fcabf !important;
    border-color: #1fcabf !important;
  }
  input[aria-checked="true"] + .n-checkbox-icon-wrapper svg,
  #mainContent input[aria-checked="true"] + .n-checkbox-icon-wrapper svg {
    color: #07232a !important;
  }
  [data-testid="search-submit"] {
    background-color: #1fcabf !important;
    color: #07232a !important;
    border-color: #1fcabf !important;
  }
  /* Autosuggest / location dropdown panels */
  [data-testid="search-autosuggession"] [role="listbox"],
  [data-testid="suggestions"], .suggestions,
  [class*="autosuggest"] ul, [class*="dropdown"] ul {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* ============================================================
     Category quick-menu (homepage tiles)
     ============================================================ */
  [data-testid="home-categories-menu"],
  [data-cy="home-categories-menu"],
  [data-testid="home-categories-menu-row"],
  [data-testid^="cat-"], [data-cy^="cat-"] {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  /* Category tile LABEL is a <p> inside a[data-testid="cat-N"] carrying
     its own near-black -webkit-text-fill-color — set both so it reads. */
  [data-testid="home-categories-menu"] p,
  [data-testid^="cat-"] p, [data-cy^="cat-"] p,
  [data-testid^="cat-"] span, [data-cy^="cat-"] span {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* The sponsored category tiles ([data-testid^="cat-promo-"]) are the LAST few
     tiles of the same grid as the ordinary [data-testid^="cat-"] ones, and OLX
     gives them no surface of their own — every tile is transparent on the page.
     Painting only the promo ones elevated turned the tail of the last row into
     one unbroken lighter slab (they sit flush against each other), which reads
     as a stray highlight cutting the grid in half. Match their plain siblings. */
  [data-testid="home-page"] [data-testid^="cat-promo-"] {
    background-color: transparent !important;
    border-color: #2d333b !important;
  }

  /* Homepage content headings/text (e.g. the "OLX dla biznesu"
     business-promo band) ship near-black #14181d that vanishes once
     the band is flattened to dark. Remap content text under the
     home-page container, forcing -webkit-text-fill-color too. */
  [data-testid="home-page"] h1,
  [data-testid="home-page"] h2,
  [data-testid="home-page"] h3,
  [data-testid="home-page"] h4 {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  [data-testid="home-page"] p {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* SEO link lists at the bottom of the homepage ("Kategorie główne:"
     and "Popularne wyszukiwania:") are <a> elements carrying the
     near-black #02282c -webkit-text-fill token — they render fully
     dark-on-dark. Lift the home-page link text (and its inner span)
     to a legible muted grey; the category tiles inherit the same and
     stay readable. Brand CTAs live in the header, not here. */
  [data-testid="home-page"] a,
  [data-testid="home-page"] a span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  [data-testid="home-page"] a:hover,
  [data-testid="home-page"] a:hover span {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }

  /* The homepage "site information" block (big OLX wordmark, SEO blurb and the
     "Dołącz do nas" Facebook / Instagram / TikTok / YouTube / LinkedIn /
     Pinterest row) draws its glyphs with fill="currentColor" over the literal
     near-black #02282c, so both the wordmark and five of the six social icons
     rendered invisible on the dark base. The Pinterest mark carries no fill at
     all and falls back to SVG's default black — force currentColor on the
     paths so it follows the link colour like its siblings. All six marks are
     monochrome, so nothing brand-coloured is flattened here. */
  #mainContent [data-testid="site-information"] > svg,
  #mainContent [data-testid="site-information"] a svg {
    color: #9aa6b0 !important;
  }
  #mainContent [data-testid="site-information"] a svg path,
  #mainContent [data-testid="site-information"] a svg g {
    fill: currentColor !important;
  }
  #mainContent [data-testid="site-information"] a:hover svg {
    color: #e6edf3 !important;
  }

  /* ============================================================
     Listing / ad cards
     The blanket neutraliser above (#mainContent div) out-specifies a
     bare [data-testid="l-card"], so the card re-opaque rules are
     anchored under the stable page container ids to win the cascade.
     ============================================================ */
  #mainContent [data-testid="l-card"],
  #searchmain-container [data-testid="l-card"],
  #mainContent [data-cy="l-card"] {
    background-color: #1c2128 !important;
    border: 1px solid #2d333b !important;
    border-radius: 8px !important;
  }
  /* Image placeholder block inside cards (grey #ECEEEF). OLX's card link now
     holds TWO `a > div` children: the FIRST is the photo container (holds the
     <img>), the SECOND is an absolutely-positioned overlay (favourite heart /
     badges) laid ON TOP of the photo. Painting a bare `a > div` opaque #21262d
     covered every loaded photo with the overlay. Scope the dark placeholder to
     the FIRST child only — it shows through as a dark box on image-less cards
     while the overlay stays transparent so loaded photos are visible. */
  #mainContent [data-testid="l-card"] a > div:first-child,
  #searchmain-container [data-testid="l-card"] a > div:first-child,
  #mainContent [data-testid="l-card"] figure {
    background-color: #21262d !important;
  }
  /* Card title is an <h4> inside [data-testid="ad-card-title"] with its
     own near-black -webkit-text-fill-color — set both on title + child. */
  [data-testid="ad-card-title"],
  [data-cy="ad-card-title"],
  [data-testid="ad-card-title"] a,
  [data-cy="ad-card-title"] a,
  [data-testid="ad-card-title"] h4,
  [data-testid="ad-card-title"] h3 {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  [data-testid="ad-price"] {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
    font-weight: 700 !important;
  }
  [data-testid="location-date"] {
    color: #8b949e !important;
    -webkit-text-fill-color: #8b949e !important;
  }
  /* Search results count line ("Znaleźliśmy ponad 1000 ogłoszeń") */
  #mainContent [data-testid="listing-count-msg"],
  #mainContent [data-testid="listing-count-msg"] *,
  #mainContent [data-testid="total-count"],
  #mainContent [data-testid="total-count"] * {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* Promoted "z Pakietem Ochronnym" price badge text */
  [data-testid="btr-label-wrapper"],
  [data-testid="btr-label-wrapper"] *,
  [data-testid="btr-label-text"] {
    color: #6fe3da !important;
    -webkit-text-fill-color: #6fe3da !important;
  }

  /* Delivery / promoted / negotiable badges */
  [data-testid="card-delivery-badge"],
  [data-testid="btr-label-wrapper"],
  [data-testid="free-delivery-tag"] {
    background-color: #103c3b !important;
    border-color: #1fcabf !important;
  }
  /* free-delivery-tag ships a light mint (#C8F8F6) fill + dark teal
     text — flip the fill to the dark accent-subtle and lift the text. */
  [data-testid="free-delivery-tag"],
  [data-testid="free-delivery-tag"] * {
    color: #6fe3da !important;
    -webkit-text-fill-color: #6fe3da !important;
  }
  /* The delivery pills sit under #mainContent / #searchmain-container, where the
     blanket neutraliser (`#mainContent div`, 1,0,1) out-specifies the bare
     [data-testid] fill above (0,1,0) and strips it to transparent — so on the
     listing the badge lost its dark-accent pill and rendered as naked mint text
     floating on the card photo (contrast then depends on the user's photo).
     Re-assert the pill scoped under the page containers so it wins the cascade. */
  #mainContent [data-testid="free-delivery-tag"],
  #mainContent [data-testid="card-delivery-badge"],
  #searchmain-container [data-testid="free-delivery-tag"],
  #searchmain-container [data-testid="card-delivery-badge"] {
    background-color: #103c3b !important;
    border-color: #1fcabf !important;
  }

  /* Condition badge ("Nowe" / "Używane" / "Uszkodzone") — the card's other Nexus badge,
     a solid #F2F4F5 pill on the light card. It carries no testid of its own, so the
     blanket neutraliser stripped its fill and it rendered as bare text right beside the
     delivery pill that kept one: the two chips stopped reading as the same kind of
     control. Give it the raised surface the rest of the card's chrome uses. The delivery
     badge is the SAME component, so the selector reaches it too and its mint pill is
     re-asserted below at equal specificity (later source wins). The mobile host has no
     #mainContent, so its ad-card twin is covered separately. */
  #mainContent [data-testid="l-card"] [data-nx-name="NexusBadge"],
  #searchmain-container [data-testid="l-card"] [data-nx-name="NexusBadge"],
  [data-testid="ad-card"] [data-nx-name="NexusBadge"] {
    background-color: #21262d !important;
  }
  #mainContent [data-testid="l-card"] [data-testid="free-delivery-tag"],
  #mainContent [data-testid="l-card"] [data-testid="card-delivery-badge"],
  #searchmain-container [data-testid="l-card"] [data-testid="free-delivery-tag"],
  #searchmain-container [data-testid="l-card"] [data-testid="card-delivery-badge"],
  [data-testid="ad-card"] [data-testid="free-delivery-tag"],
  [data-testid="ad-card"] [data-testid="card-delivery-badge"] {
    background-color: #103c3b !important;
    border-color: #1fcabf !important;
  }

  /* "Wyróżnione" (Featured/highlighted-ad) badge, the card's data-nx-name="Tag"
     component (delivery/promoted badges have their own testids). It is NOT bare
     text on the light site: it is a SOLID OLX-mint (#23E5DB) pill with a
     near-black label, laid over the photo — the strongest badge on the card. The
     blanket `#mainContent div` neutraliser stripped that mint fill, leaving the
     label as naked text sitting directly on the user's photo, so its contrast
     depended entirely on the picture behind it (over a bright thumbnail it
     disappeared). Restore the pill on the accent and put the dark label back on
     it, so "featured" keeps both its identity and its legibility. */
  /* The search/category grid renders the "Wyróżnione" badge into a separate
     badge-portal overlay (positioned over each card photo), NOT inside
     [data-testid="l-card"] — so the card-scoped rule above never reached it and
     the blanket `#mainContent div` neutraliser stripped its mint fill, leaving
     the near-black label floating dark-on-dark on the photo. OLX has renamed
     the portal root across deploys (`listing-ad-badge-portal-root` →
     `listing-item-badge-portal-root`), so match the stable `badge-portal`
     fragment they share rather than either full class. The portal holds ONLY
     these featured Tags (delivery/promoted badges carry their own testids), so
     mint every Tag under it too. */
  #mainContent [data-testid="l-card"] [data-nx-name="Tag"],
  #searchmain-container [data-testid="l-card"] [data-nx-name="Tag"],
  #mainContent [class*="badge-portal"] [data-nx-name="Tag"] {
    background-color: #1fcabf !important;
    border-color: #1fcabf !important;
  }
  #mainContent [data-testid="l-card"] [data-nx-name="Tag"],
  #mainContent [data-testid="l-card"] [data-nx-name="Tag"] *,
  #searchmain-container [data-testid="l-card"] [data-nx-name="Tag"],
  #searchmain-container [data-testid="l-card"] [data-nx-name="Tag"] *,
  #mainContent [class*="badge-portal"] [data-nx-name="Tag"],
  #mainContent [class*="badge-portal"] [data-nx-name="Tag"] * {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }

  /* Partner-brand chip on the promoted/partner cards ([data-testid="adCard-partner"] —
     the OTOMOTO / Otodom / obido wordmark laid over the card photo). OLX plates it with
     the near-black #02282c inverse fill so the white wordmark reads on any picture; the
     blanket `#mainContent div` neutraliser strips that plate and the mark floats
     directly on the user's photo (gone over a bright one). The plate is the chip's only
     child div; anchor it under the page containers so it out-specifies the neutraliser
     and keep the native near-black, which is what the white wordmark is drawn for. */
  #mainContent [data-testid="adCard-partner"] div,
  #searchmain-container [data-testid="adCard-partner"] div {
    background-color: #02282c !important;
  }

  /* The homepage "recommended"/partner (Storia real-estate) l-card variant
     adds a secondary parameter line — area / rooms, e.g. "352 m²" — inside an
     un-testid'd <span> carrying the dim #406367 token, so it renders low
     contrast on the dark card. Lift every card param <span> to a legible muted
     grey. The price is a <p> and the title an <h4> (not spans), so they stay
     untouched; the mint promoted/delivery badges and the white price are
     re-asserted just below so this broader span rule can't grey them out. */
  #mainContent [data-testid="l-card"] span,
  #searchmain-container [data-testid="l-card"] span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  /* Services ads (and the whole seller-profile listing) hang "specialisation"
     chips under the title — "Elewacje i tynkowanie", "+3 więcej", … Each chip
     is a nested <span> with a literal `background:#FFFFFF` and a 1px #D8DFE0
     outline: a white pill on a white card, i.e. really just an outline chip.
     The blanket neutraliser only reaches div/section/article/ul, so the white
     survived while the param-lift above dimmed the label to #9aa6b0 — 1.6:1,
     unreadable. Drop the fill and let the (already softened) outline carry the
     pill; `transparent` is a no-op on every other span, and the card's delivery
     / promoted / "Wyróżnione" badges are <div>s, so none of them are flattened. */
  #mainContent [data-testid="l-card"] span > span,
  #searchmain-container [data-testid="l-card"] span > span {
    background-color: transparent !important;
  }
  /* Re-assert semantic card colours the param-lift above would otherwise flatten */
  #mainContent [data-testid="l-card"] [data-testid="ad-price"],
  #mainContent [data-testid="l-card"] [data-testid="ad-price"] span,
  #searchmain-container [data-testid="l-card"] [data-testid="ad-price"],
  #searchmain-container [data-testid="l-card"] [data-testid="ad-price"] span {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
  #mainContent [data-testid="l-card"] [data-testid="btr-label-wrapper"] span,
  #mainContent [data-testid="l-card"] [data-testid="btr-label-text"],
  #mainContent [data-testid="l-card"] [data-testid="free-delivery-tag"] span,
  #searchmain-container [data-testid="l-card"] [data-testid="btr-label-wrapper"] span,
  #searchmain-container [data-testid="l-card"] [data-testid="free-delivery-tag"] span {
    color: #6fe3da !important;
    -webkit-text-fill-color: #6fe3da !important;
  }

  /* …but [data-testid="ad-price"] IS the price <p> (the amount is its own text node)
     and its only children are Nexus Label2 <span>s carrying the price QUALIFIER
     ("do negocjacji", "od"). OLX ranks those a step down — dim #406367 against the
     near-black #02282c amount — while the ` span` arms of the white rules above painted
     them the same #ffffff as the amount, so the qualifier shouted as loudly as the
     price. Hand the step back; ties the l-card rule on specificity, so it has to stay
     after it. */
  #mainContent [data-testid="ad-price"] span[data-nx-name="Label2"],
  #searchmain-container [data-testid="ad-price"] span[data-nx-name="Label2"],
  [data-testid="ad-card"] [data-testid="ad-price"] span[data-nx-name="Label2"] {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }

  /* Favourite (heart) toggle. The heart is an inline <svg> whose <path> is
     fill="currentColor", and OLX sets the colour on the SVG itself through a
     hashed emotion class carrying a literal #02282c — so colouring the wrapping
     <button> (which the theme already did) never reached the artwork and the
     heart rendered near-black on the dark card. Colour the SVG directly. */
  [data-testid="adAddToFavorites"],
  [data-testid="adAddToFavorites"] svg,
  [data-testid="observe-ad"] svg { color: #c4cdd6 !important; }

  /* Native "SPONSOROWANE" ads (OLX baxter native template) render inside the
     listing grid as plain HTML carrying their own near-black #02282c
     -webkit-text-fill token, so once the grid goes dark the ad title,
     advertiser line and the "i" attribution popup all fall dark-on-dark.
     Anchor on the stable #baxter-native-listing* id (the -olx-<tld>- segment
     varies per country) and lift the text; brighten the headline; flatten the
     small light info chip + the white attribution popup so it reads too. */
  [id^="baxter-native-listing"],
  [id^="baxter-native-listing"] * {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  [id^="baxter-native-listing"] [class*="title"] {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  /* Natively the SPONSOROWANE card is a white panel exactly like the organic
     l-cards it sits between, but nothing ever gave it a surface here — so it was
     the one row of the results grid with no card at all, reading as loose text on
     the page while every neighbour kept its raised box. The root carries the whole
     card (there is no inner wrapper on this desktop template), and it sits under
     the blanket `#mainContent div` neutraliser (1,0,1), so the rule has to be
     anchored on a page container to win. Same surface as the l-card rule. */
  #mainContent [id^="baxter-native-listing"],
  #searchmain-container [id^="baxter-native-listing"] {
    background-color: #1c2128 !important;
    border: 1px solid #2d333b !important;
    border-radius: 8px !important;
  }
  /* These surfaces sit inside #mainContent, so the blanket neutraliser
     (`#mainContent div`, specificity 1,0,1) out-specifies a bare
     [id^=…] [class*=…] (0,2,0) and the background never landed: the ad's
     "Informacja o tej reklamie" popup rendered fully SEE-THROUGH over the
     creative, and the mint "SPONSOROWANE" disclosure band lost its tint
     entirely. Anchor under #mainContent (1,2,0) so they actually paint.
     The popup's downward caret is a real-element CSS triangle whose left/right
     borders must stay transparent — the blanket `* { border-color }` reset
     painted all four sides, so it rendered as a solid grey rectangle. */
  #mainContent [id^="baxter-native-listing"] [class*="attribution"],
  #mainContent [id^="baxter-native-listing"] [class*="popup"],
  #mainContent [id^="baxter-native-listing"] [class*="tooltip"] {
    background-color: #103c3b !important;
    border-color: #2d333b !important;
  }
  /* `…_spnu` is the template's CONDITION chip ("Nowe" / "Używane" — it sits inside
     `…__nu`, nowe/używane), NOT part of the SPONSOROWANE disclosure: natively it is the
     same neutral #F2F4F5 pill every organic l-card carries. Grouped with the mint
     disclosure surfaces it became the only condition chip on the page wearing the
     ad-tint, reading as a delivery/promoted badge. Match its l-card twin instead. */
  #mainContent [id^="baxter-native-listing"] [class*="_spnu"] {
    background-color: #21262d !important;
  }
  /* The popup's close ✕ is two STROKED line segments carrying a literal
     stroke="black" (no fill at all — a `fill` override paints nothing). The
     `#mainContent svg { color: inherit }` icon rule sets `color`, which a path that
     never says `currentColor` cannot read, so on the light popup black was correct and
     on our dark panel the only control that dismisses it sat at ~1.5:1. Point the
     stroke at the colour its container already carries. */
  #mainContent [id^="baxter-native-listing"] [class*="link_close"] svg path {
    stroke: currentColor !important;
  }
  #mainContent [id^="baxter-native-listing"] [class*="attribution-link"] {
    background-color: #1c2128 !important;
    border-color: #83a4ec !important;
  }
  #mainContent [id^="baxter-native-listing"] [class*="template__after"] {
    border-top-color: #83a4ec !important;
    border-right-color: transparent !important;
    border-left-color: transparent !important;
  }

  /* OLX's ad server pins a "ZAMKNIJ X" close button over each sticky/expandable
     slot with an INLINE `background: white` (not !important). Its label has no
     colour of its own, so it inherits the body text colour — which we flipped
     to light — and the only control that dismisses the ad became white-on-white.
     Give it the elevated dark surface it now needs. */
  /* Its host slot `.baxter-inner-sticky` is a literal white bar sized to the viewport
     while the creative inside it is a fixed 320px iframe, so on a 390px phone the ad
     sits in a bright white frame — 35px of white down each side plus the strip the
     close button sits on. Only the button had been darkened. */
  .baxter-inner-sticky {
    background-color: #14181d !important;
  }
  .baxter-inner-sticky-close-button {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
    box-shadow: none !important;
  }

  /* Offer pages also inject an in-page ING loan-calculator native ad
     (#inter-box_ad-detail inside a qa-advert-slot) rendered as plain HTML.
     Its legal disclaimer ("RRSO … ING Bank Śląski S.A.") and the "Zobacz
     koszty kredytu" link carry a literal near-black colour, so once the box
     flattens to the dark base they render dark-on-dark and vanish. Lift its
     dark subtitle/footer text to a legible muted grey; the white headline,
     the grey slider labels and the accent "Oblicz ratę" button keep their
     own colour. Force -webkit-text-fill-color too (OLX drives text fill). */
  #inter-box_ad-detail .inter-box_subtitle_middle,
  #inter-box_ad-detail .inter-box_subtitle_bottom,
  #inter-box_ad-detail .inter-box_subtitle_middle *,
  #inter-box_ad-detail .inter-box_subtitle_bottom * {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  /* Its amount / term fields are `input[type="number"]` on a literal #eeeeee,
     and the "zł" / "msc" unit suffix is a white .inter-box_spec pill. The
     theme's generic input rule only listed text/search inputs, so the amount
     inherited the light text colour and read light-on-light. */
  #inter-box_ad-detail input[type="number"],
  #inter-box_ad-detail .inter-box_spec {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  /* ING brands the calculator in its orange: an #FF6200 "Oblicz ratę" CTA and
     #F2A066 field outlines. The CTA is a `button[type="submit"]`, so the OLX
     accent rule further down repainted an advertiser's brand button OLX teal,
     and the blanket border reset erased the field outlines. Give them back. */
  #inter-box_ad-detail .calculator_button_cta {
    background-color: #ff6200 !important;
    border-color: #ff6200 !important;
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
  #inter-box_ad-detail input[type="number"] { border-color: #f2a066 !important; }
  #inter-box_ad-detail .inter-box_spec { border-color: #2d333b !important; }
  /* The calculator's masthead is a full-width #FF6200 band carrying a white
     headline: the advertiser's brand plate, and the only thing separating this
     block from OLX's own content under the "Płatna współpraca" label. It is a
     plain <div> under #mainContent, so the blanket neutraliser (1,0,1) strips
     it; the slot id in the selector (1,1,0) out-specifies that. */
  #inter-box_ad-detail .inter-box_sub-title_wrapper {
    background-color: #ff6200 !important;
  }
  #inter-box_ad-detail .inter-box_sub-title_wrapper,
  #inter-box_ad-detail .inter-box_sub-title_wrapper * {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }

  /* The one-line loan teaser (`a.creditbox`, served next to the price in the
     right rail and again inside the photo lightbox) is a sibling of the same ING
     family. Two things break on dark: its leading calculator glyph is a raster
     <img> baked on a WHITE tile — invisible on the light card, a glaring white
     square here — and its headline is a hardcoded #3473FE that lands at ~4.3:1
     on the page base, under AA. Invert the monochrome tile so the glyph keeps its
     shape on a dark ground, and lift the blue enough to read while staying
     recognisably the advertiser's link colour. The headline element varies by
     deploy — a <strong>, or a bare <span class="ing_gal_span"> carrying the hex
     as an INLINE style — so cover both. */
  .creditbox img { filter: invert(1) !important; }
  .creditbox strong,
  .creditbox span,
  .creditbox span strong {
    color: #8ab4ff !important;
    -webkit-text-fill-color: #8ab4ff !important;
  }

  /* OLX's SSR ad slots (e.g. #baxter-top on the offer/listing pages) ship a
     full-width house-ad placeholder ("OLX REKLAMA") baked onto a WHITE canvas
     as a background-IMAGE, so the unfilled slot renders as a glaring white
     banner on dark. Because the white is a raster background-image (not a
     bg-color, and not a light gradient stop) BOTH the element-bg scan and the
     light-gradient scan miss it. Strip the placeholder image and drop the slot
     onto the dark base — a real ad loading into the slot lives in its own child
     iframe, so it is unaffected. Two class conventions ship these placeholders:
     `*-baxter-ssr-placeholder`/`with-placeholder-image` (e.g. #baxter-top on the
     offer/listing) and `baxter-placeholder--*` (e.g. #baxter-seller-billboard on
     the profile) — cover both. */
  [class*="ssr-placeholder"],
  [class*="baxter-placeholder"],
  [class*="with-placeholder-image"] {
    background-image: none !important;
    background-color: #14181d !important;
  }

  /* ============================================================
     Top promo / info banner strip (was pale yellow #FFF6D9)
     ============================================================ */
  #banner, #banner > div,
  #mainContent [data-testid="top-banner-wrapper"],
  #mainContent [data-testid="cta-banner-click"] {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  #mainContent [data-testid="banner-btn"],
  #mainContent [data-testid="bep-button"] {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  /* `banner-btn` is shared by two very different banners. The top info/scam strip
     publishes its button as the site's own `flat` variant, for which the neutral chip
     above is right. The homepage "OLX dla biznesu" band ([data-testid="business-banner"],
     a full-width `!bg-background-inverse` near-black sheet) publishes ITS CTA as
     `primary` and paints it a SOLID WHITE pill with a near-black label — the band's
     only action. The chip fill turned that into a dim slab on an almost-equally-dark
     band. Key on the variant OLX itself publishes and hand the primary the accent every
     other primary CTA in the theme gets; its label <span> also carries the near-black
     text-fill, so both channels have to be set. */
  #mainContent [data-testid="banner-btn"][data-button-variant="primary"],
  #mainContent [data-testid="bep-button"][data-button-variant="primary"] {
    background-color: #1fcabf !important;
    border-color: #1fcabf !important;
  }
  #mainContent [data-testid="banner-btn"][data-button-variant="primary"],
  #mainContent [data-testid="banner-btn"][data-button-variant="primary"] span,
  #mainContent [data-testid="bep-button"][data-button-variant="primary"],
  #mainContent [data-testid="bep-button"][data-button-variant="primary"] span {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }

  /* ============================================================
     Search-results page: filters sidebar, sort dropdowns, pills
     ============================================================ */
  /* The current OLX frontend nests the whole search/category page
     (filters + listing grid) under #mainContent — the old
     #searchmain-container id no longer exists, so these are anchored
     on #mainContent (and the stable filter/listing testids) which is
     where they actually live now. */
  #mainContent [data-testid="listing-filters"],
  #mainContent [data-testid="filters-container"],
  #mainContent [data-testid="qsearch-container"],
  #mainContent [data-testid="listing-filters-form"],
  #mainContent [class*="filter"] [role="button"],
  #mainContent [data-testid="chips-container"] > * {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }
  /* Filter FIELDS inside that panel. Natively every one of them is a white box
     on the grey #F2F4F5 filter sheet — that white IS the whole field boundary
     (OLX draws no border: border-width is 0). Only the category dropdown reads
     its surface from a token we remap, so it kept a box; the price range inputs
     and the multi-select heads take their white from a hashed emotion wrapper
     that the blanket `#mainContent div` neutraliser strips, so "Od"/"Do"/"Stan"
     rendered as bare labels floating on the panel with nothing to click. Sink
     them to the page base like the category dropdown so all four fields match. */
  #mainContent [data-testid="range-from-flyout-toggle"] > div,
  #mainContent [data-testid="range-to-flyout-toggle"] > div,
  #mainContent .multi-select-head {
    background-color: #14181d !important;
  }
  /* …and the range <input> itself is transparent natively (the field surface is
     the wrapper above). The generic input rule fills it #1c2128, which is exactly
     the filter panel's colour, so the left half of each price field disappeared
     and only the chevron half read as a box. Let the wrapper carry the surface. */
  #mainContent [data-testid="range-from-input"],
  #mainContent [data-testid="range-to-input"] {
    background-color: transparent !important;
  }
  /* Currency switch (olx.ro "Moneda: lei €"). OLX ranks the two by colour alone —
     the selected currency is the near-black #02282C, the other the dim #406367 —
     and the filter-panel span lift painted BOTH #c4cdd6, so the active currency
     became indistinguishable from the inactive one. Both are <span>s inside the
     filter panel, so the pair has to carry the panel scope as well or the
     blanket `…[data-testid="listing-filters"] span` lift (1,2,0) out-specifies
     it and nothing changes. */
  #mainContent [data-testid="currency-item-selected"],
  #mainContent [data-testid="listing-filters"] [data-testid="currency-item-selected"] {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  #mainContent [data-testid="currency-item"],
  #mainContent [data-testid="listing-filters"] [data-testid="currency-item"] {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  /* The search/category column sits INSIDE a position:relative; z-index:3 wrapper
     (the only stacking layer that paints above OLX's full-bleed "screening"
     wallpaper ad, a position:fixed z-index:1 iframe). Natively that wrapper is an
     opaque #F2F4F5 sheet 24px wider than the listing form it holds, so the ad only
     ever shows in the page gutters. The blanket `#mainContent div` neutraliser
     turned it transparent, so the wallpaper ad bled back through the 24px inset —
     a bright blue frame down both edges of the results column and a band above the
     footer. It is the last div under #mainContent's shell (the SSR ad slot is its
     only sibling), so anchor it structurally and give it the page base back.
     The listing FORM is corrected to the base at the same time: it is the PAGE
     under the cards, not a card itself (natively the grey #F2F4F5 sheet), and the
     rule above had it at the #1c2128 card elevation — so every l-card sat at
     exactly its own container's colour and the cards' elevation disappeared. */
  #mainContent > div > div:last-of-type,
  #mainContent form[data-testid="listing-filters-form"] {
    background-color: #14181d !important;
  }
  [data-testid="pagination-wrapper"] a,
  [data-testid="pagination-list"] li {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  [data-testid="pagination-forward"],
  [data-testid="pagination-back"] { color: #e6edf3 !important; }
  /* Current page. OLX marks it with a SOLID near-black #02282c fill drawn from
     the `background-inverse` token — the strongest fill on the white page. We
     remap that token to #0d1117, which lands at 1.08:1 on the #14181d base, so
     the "you are here" box became invisible and page 1 read exactly like pages
     2-25. The button is the only one in the list carrying aria-current="page"
     (the other pages are <a>), so key on that and give it the accent fill the
     theme already uses for every other selected state. */
  #mainContent [data-testid="pagination-wrapper"] button[aria-current="page"] {
    background-color: #1fcabf !important;
    border-color: #1fcabf !important;
  }
  #mainContent [data-testid="pagination-wrapper"] button[aria-current="page"],
  #mainContent [data-testid="pagination-wrapper"] button[aria-current="page"] span {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }
  /* The seller-profile "Oceny" (ratings) tab paginates with the LEGACY Nexus
     component (data-nx-name="Pagination", data-nx-legacy="true") — a <ul> of
     <li><button> page numbers that carries none of the pagination-* testids the
     rules above target. Each page-number button ships the literal near-black
     #02282c on its own colour (not a token), so "2 3 4 … 14" rendered dark-on-dark
     and only the current-page ring + the prev/next arrows read. Lift the button
     labels to legible grey; the active page keeps its accent ring. */
  [data-nx-name="Pagination"] button {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* …and this component marks its CURRENT page with a 2px `outline` (not a border,
     not a box-shadow) in the literal near-black #02282c — 1.14:1 on the page base,
     so "you are here" disappeared and page 1 read exactly like 2-15 once the labels
     above were all lifted to the same grey. Nothing else on any page type draws a
     low-contrast outline, so this is the theme's only outline rule. Note the hook:
     the listing pagination publishes aria-current="page" and gets an accent FILL a
     few rules up; this legacy one publishes aria-current="true". */
  [data-nx-name="Pagination"] button[aria-current="true"] {
    outline-color: #1fcabf !important;
  }

  /* Search-results heading (h1[data-testid="heading"], "Sprzedaż
     elektroniki") + filter/sort labels + filter values all carry the
     near-black #02282c / dim #406367 content colour. Remap them under
     the listing-filters form / sorting wrapper and force
     -webkit-text-fill-color so the override wins. */
  #mainContent [data-testid="heading"],
  #mainContent [data-testid="listing-filters-form"] h1,
  #mainContent [data-testid="listing-filters-form"] h2,
  #mainContent [data-testid="listing-filters-form"] h3 {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  #mainContent [data-testid="listing-filters-form"] p,
  #mainContent [data-testid="listing-filters-form"] label,
  #mainContent [data-testid="listing-filters"] p,
  #mainContent [data-testid="listing-filters"] span,
  #mainContent [data-testid^="category-filter"] p,
  #mainContent [data-testid^="category-filter"] span,
  #mainContent [data-testid="filter-clear-all"],
  #mainContent [data-testid="filter-clear-all"] span,
  #mainContent [data-testid="sorting-wrapper"],
  #mainContent [data-testid="sorting-wrapper"] span {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* "Wyczyść filtry" is the panel's only reset, and OLX marks it purely by hover
     (#406367 darkening to #02282c). The lift above is `!important`, so it pinned the
     label and the control stopped answering the pointer entirely. Brighten it the way
     the site strengthens it. */
  #mainContent [data-testid="filter-clear-all"]:hover,
  #mainContent [data-testid="filter-clear-all"]:hover span {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  /* Filter segmented-control values (Wszystkie / Firmowe / Prywatne)
     are <span> inside <button> in a filter <header> — flip to legible. */
  #mainContent [data-testid="listing-filters"] button span,
  #mainContent [data-testid="listing-filters-form"] button span {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* "Zapisz" save-search CTA: accent fill, dark legible label */
  #mainContent [data-testid="save-search-button"],
  #mainContent [data-testid="save-search-form-submit"],
  #mainContent [data-testid="l-save-search-banner-button"] {
    background-color: #1fcabf !important;
    border-color: #1fcabf !important;
  }
  #mainContent [data-testid="save-search-button"],
  #mainContent [data-testid="save-search-button"] span,
  #mainContent [data-testid="save-search-form-submit"],
  #mainContent [data-testid="save-search-form-submit"] span,
  #mainContent [data-testid="l-save-search-banner-button"],
  #mainContent [data-testid="l-save-search-banner-button"] span {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }
  /* …but on a search/category page BOTH accent CTAs — the hero "Szukaj" submit and
     the "Zapisz" save-search button — live inside [data-testid="listing-filters-form"],
     and the segmented-control rule above (`…listing-filters-form button span`, 1,1,2)
     out-specifies the attribute-only label rules (1,1,1) that were meant to keep them
     dark-on-mint. So their <span> labels resolved to the light #c4cdd6 and rendered at
     1.27:1 on the mint fill — the page's primary search button read as an empty teal
     slab next to its own (correctly dark) magnifier glyph. Re-assert the dark label
     with the <button> type in the selector so it ties on specificity and wins on
     source order. */
  #mainContent button[data-testid="search-submit"],
  #mainContent button[data-testid="search-submit"] span,
  #mainContent button[data-testid="save-search-button"] span,
  #mainContent button[data-testid="save-search-form-submit"] span,
  #mainContent button[data-testid="l-save-search-banner-button"] span {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }

  /* Footer SEO sub-category link list (Fotografia / Komputery / … )
     at the bottom of search/category pages ships dim #406367 link text
     via its own -webkit-text-fill-color — lift it to a legible muted
     grey. These links live in <ul><li><a> blocks under #mainContent. */
  #mainContent ul li a,
  #mainContent ul li a span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  #mainContent ul li a:hover,
  #mainContent ul li a:hover span {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }

  /* ============================================================
     Seller / user profile page (/oferty/uzytkownik/)

     A distinct #mainContent layout whose profile-header follow/share
     buttons, the "Wszystkie ogłoszenia / Oceny" tab bar, the filter &
     sort section labels, the result-count line, the seller metadata
     and the card location lines all ship the near-black #02282c / dim
     #406367 content tokens through -webkit-text-fill-color, so they
     render dark-on-dark. The offer/search remaps are anchored on
     testids this page doesn't use — cover its stable anchors here.
     ============================================================ */
  /* Profile tab bar — inactive tabs only; the active one keeps the brighter
     label + accent underline set in the tab block near the top of the file. */
  #mainContent button[data-is-active="false"],
  #mainContent button[data-is-active="false"] span {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* (The profile-header Obserwuj / Podziel się buttons used to need a
     parent-match rule here. They are Nexus secondary/tertiary buttons whose
     label reads the foreground-action-primary token, so the token remap at the
     top of the file now covers them — the .org.css build drops no rule.) */

  /* Filter/sort section labels (Kategorie / Sortuj / Znajdź na tej
     stronie) — lift, then re-assert the card title/price the broad
     seller-listing rule would otherwise flatten. */
  #mainContent [data-testid="seller-listing"] h4,
  #mainContent [data-testid="seller-listing"] > header,
  #mainContent [data-testid="seller-listing"] > header * {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  #mainContent [data-testid="seller-listing"] [data-testid="ad-card-title"],
  #mainContent [data-testid="seller-listing"] [data-testid="ad-card-title"] h4 {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  /* Shop/store subdomain (e.g. luxtradestore7.olx.<tld>) renders the seller's
     ad list under [data-testid="shop-listing-desktop-layout"], NOT the
     seller-listing hook above — a separate frontend the profile rules miss.
     Its left filter panel's "Kategorie" section heading (and the result-count
     heading) are <h4>s carrying the hardcoded dim #406367 (not a token), so
     "Kategorie" rendered near-invisible dark-on-dark. The store l-cards carry
     NO heading elements, so lifting every <h4> in this layout touches only the
     two sidebar headings and cannot flatten a card title. */
  #mainContent [data-testid="shop-listing-desktop-layout"] h4 {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* Result count + seller metadata (member-since / last-online) + card
     location lines (bare <p>, no location-date testid on this variant) */
  #mainContent [data-testid="results-counter"],
  #mainContent [data-testid="results-counter"] *,
  #mainContent [data-testid="lastSeenBox"],
  #mainContent [data-testid="lastSeenBox"] *,
  #mainContent [data-testid="l-card"] p {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  #mainContent [data-testid="seller-listing"] [data-testid="ad-price"],
  #mainContent [data-testid="seller-listing"] [data-testid="ad-price"] * {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }

  /* ============================================================
     Individual offer / item page

     The offer content column is a stack of hashed emotion shells
     under #mainContent → div[data-testid="main"]; the blanket
     neutraliser above already flattens those literal light bands.
     Here we (a) RE-ESTABLISH opaque dark on the real floating cards
     (out-specifying the neutraliser via #mainContent), and (b) remap
     the near-black content text. OLX drives rendered text through
     -webkit-text-fill-color, so a `color`-only override silently
     fails — every text rule sets BOTH color and -webkit-text-fill.
     ============================================================ */
  /* Distinct cards within the offer page -> elevated surface */
  #mainContent [data-testid="ad-action-box"],
  #mainContent [data-testid="seller_card"],
  #mainContent [data-testid="map-aside-section"],
  #mainContent [data-testid="legal-information-accordion"],
  #mainContent [data-testid="user-profile-link"],
  #mainContent [data-testid="qa-skeleton-item"],
  #mainContent [data-testid="ad-card-loader"],
  #mainContent [data-testid="ad-login-dialog"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* In-content seller-contact card (white box under main > section) */
  #mainContent [data-testid="main"] > section > div {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* Nexus info banner (the "Oceny … są weryfikowane" note in the seller card,
     in the bottom SKONTAKTUJ SIĘ block and on the profile's Oceny tab). It is a
     tinted callout natively — #CEDDFF light blue on the offer, #C8F8F6 mint on
     the profile — and the mobile rule further down already sinks it. On desktop
     that rule loses: the blanket `#mainContent div` neutraliser (1,0,1) strips
     the tint, so the callout dissolved into plain paragraph text on the card.
     Re-assert it scoped under the page containers so it out-specifies (1,2,0).
     The homepage's InPost strip is a Banner too but keeps its own
     top-banner-wrapper surface, so it is deliberately left out of this list. */
  #mainContent [data-testid="main"] [data-nx-name="Banner"],
  #mainContent [data-testid="aside"] [data-nx-name="Banner"],
  #mainContent #ratings [data-nx-name="Banner"] {
    background-color: #1b2436 !important;
  }

  /* ---- Offer content text (was near-black #02282c on dark) ----
     The offer TITLE is an un-testid'd <h4>, and headings/labels/
     parameter rows/desc all inherit the same near-black; remap the
     whole content column's text and force -webkit-text-fill-color
     so the override actually wins. Brand-coloured controls (accent
     CTAs, the red "Zgłoś" report button) keep their own colour via
     the more specific rules that follow. */
  #mainContent [data-testid="main"] h1,
  #mainContent [data-testid="main"] h2,
  #mainContent [data-testid="main"] h3,
  #mainContent [data-testid="main"] h4,
  #mainContent [data-cy="ad_title"], #mainContent [data-testid="offer_title"] {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  #mainContent [data-testid="main"] p,
  #mainContent [data-testid="main"] li,
  #mainContent [data-testid="ad_description"],
  #mainContent [data-testid="ad_description"] *,
  #mainContent [data-testid="ad-parameters-container"] p,
  #mainContent [data-testid="ad-parameters-container"] li,
  #mainContent [data-testid="ad-parameters-container"] span,
  #mainContent [data-testid="trader-title"],
  #mainContent [data-testid="ad-posted-at"] {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* Seller-card metadata (member-since / last-online, was #406367) */
  #mainContent [data-testid="user-profile-user-name"],
  #mainContent [data-testid="member-since"],
  #mainContent [data-testid="user-profile-link"] p,
  #mainContent [data-testid="user-profile-link"] span,
  #mainContent [data-testid="ad-footer-bar-section"] span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  /* Login prompt + its sign-in/register CTA (was #02282c dark-on-dark) */
  #mainContent [data-testid="prompt-message"] {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* Price */
  #mainContent [data-testid="ad-price-container"],
  #mainContent [data-testid="prices-wrapper"] {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  #mainContent [data-testid="prices-wrapper"] h3,
  #mainContent [data-testid="price-label"],
  #mainContent [data-testid="ad-price-value"] {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
  /* Promote / refresh action links (Promuj / Odśwież, were #02282c) */
  #mainContent [data-testid="ad-promotion-actions"] a,
  #mainContent [data-testid="ad-promotion-actions"] span,
  #mainContent [data-testid="to-back"],
  #mainContent [data-testid="to-back"] span {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* Keep the brand-red "Zgłoś" report button readable as itself */
  #mainContent [data-testid="ad-report-button"],
  #mainContent [data-testid="ad-report-button"] span {
    color: #f0795f !important;
    -webkit-text-fill-color: #f0795f !important;
  }
  /* Contact / chat / phone buttons + the login-dialog CTA -> accent
     fill with dark legible text (set BOTH color + text-fill). */
  /* The bottom "SKONTAKTUJ SIĘ" block repeats the message CTA under a different
     hook — [data-testid="chat-button"] — and paints it with OLX's near-black
     #02282c "inverse" fill instead of the accent. On white that reads as the
     primary button; on our #1c2128 card it is a 1.3:1 slab with no visible
     edge, sitting right next to the mint "Pokaż". Give it the same accent fill
     as its twin in the right rail so the two contact CTAs match. */
  /* The "Kup" safe-deal buy button ([data-testid="go-to-delivery-options"]) is
     OLX's near-black #02282c primary — the STRONGEST CTA on the light site. On
     our #1c2128 card that near-black sits at ~1.1:1, so the most important action
     on the page rendered as a near-invisible slab that reads as disabled next to
     the vivid teal message/call CTAs. It isn't in the accent group below, so give
     it the same accent fill as the other purchase CTAs. */
  /* On some domains (e.g. olx.ua) the safe-deal buy button carries NO testid —
     only data-button-variant="primary" — so the go-to-delivery-options hook
     misses it and it keeps its native near-black #02282c fill (a ~1.1:1 slab
     next to the vivid mint message/call CTAs). It is the primary button inside
     the stable [data-testid="ad-action-buttons"] container (the delivery-action
     block), which never holds a search/filter primary, so scoping the accent
     fill there catches the buy CTA on every domain without over-reaching. */
  #mainContent [data-testid="ad-contact-message-button"],
  #mainContent [data-testid="ad-contact-phone"],
  #mainContent [data-testid="show-phone"],
  #mainContent [data-testid="chat-button"],
  #mainContent [data-testid="go-to-delivery-options"],
  #mainContent [data-testid="ad-action-buttons"] button[data-button-variant="primary"],
  #mainContent [data-testid="phones-container"] button,
  #mainContent [data-testid="login-button"],
  #mainContent button[data-testid*="contact"] {
    background-color: #1fcabf !important;
    color: #07232a !important;
    border-color: #1fcabf !important;
  }
  #mainContent [data-testid="login-button"] span,
  #mainContent [data-testid="ad-contact-message-button"] span,
  #mainContent [data-testid="chat-button"] span,
  #mainContent [data-testid="go-to-delivery-options"] span,
  #mainContent [data-testid="ad-action-buttons"] button[data-button-variant="primary"] span,
  #mainContent [data-testid="phones-container"] button span {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }
  /* …but the accent group above fills EVERY contact CTA, and OLX does not: it
     ranks them. Each Nexus button carries the site's own data-button-variant, and
     on an offer with OLX delivery the rail reads primary "Kup" (a solid fill) over
     secondary "Wyślij wiadomość" / "Zadzwoń" and a tertiary login prompt (all three
     plain OUTLINE buttons). Filling all four with the same mint turned that ladder
     into four identical slabs, with nothing marking the actual purchase action — a
     wrong-but-readable state no contrast check can catch. Hand the ranking back by
     keying on the variant the site already publishes: primaries keep the accent
     fill set above, everything below primary reverts to an accent outline. Scoped
     to the contact/login CTAs so the filter and save-search buttons (also
     "secondary" components) keep the treatment they were given. */
  #mainContent [data-testid="ad-contact-message-button"][data-button-variant="secondary"],
  #mainContent [data-testid="ad-contact-message-button"][data-button-variant="tertiary"],
  #mainContent [data-testid="ad-contact-phone"][data-button-variant="secondary"],
  #mainContent [data-testid="ad-contact-phone"][data-button-variant="tertiary"],
  #mainContent [data-testid="show-phone"][data-button-variant="secondary"],
  #mainContent [data-testid="chat-button"][data-button-variant="secondary"],
  #mainContent [data-testid="login-button"][data-button-variant="secondary"],
  #mainContent [data-testid="login-button"][data-button-variant="tertiary"],
  #mainContent [data-testid="phones-container"] button[data-button-variant="secondary"],
  .n-modal-portal [data-testid="ad-contact-message-button"][data-button-variant="secondary"],
  .n-modal-portal [data-testid="chat-button"][data-button-variant="secondary"],
  .n-modal-portal [data-testid="ad-contact-phone"][data-button-variant="secondary"],
  .n-modal-portal [data-testid="show-phone"][data-button-variant="secondary"] {
    background-color: transparent !important;
    border-color: #5fd0c6 !important;
  }
  #mainContent [data-testid="ad-contact-message-button"][data-button-variant="secondary"],
  #mainContent [data-testid="ad-contact-message-button"][data-button-variant="secondary"] span,
  #mainContent [data-testid="ad-contact-phone"][data-button-variant="secondary"],
  #mainContent [data-testid="ad-contact-phone"][data-button-variant="secondary"] span,
  #mainContent [data-testid="show-phone"][data-button-variant="secondary"],
  #mainContent [data-testid="show-phone"][data-button-variant="secondary"] span,
  #mainContent [data-testid="chat-button"][data-button-variant="secondary"],
  #mainContent [data-testid="chat-button"][data-button-variant="secondary"] span,
  #mainContent [data-testid="login-button"][data-button-variant="tertiary"],
  #mainContent [data-testid="login-button"][data-button-variant="tertiary"] span,
  #mainContent [data-testid="phones-container"] button[data-button-variant="secondary"],
  #mainContent [data-testid="phones-container"] button[data-button-variant="secondary"] span,
  .n-modal-portal [data-testid="ad-contact-message-button"][data-button-variant="secondary"],
  .n-modal-portal [data-testid="ad-contact-message-button"][data-button-variant="secondary"] span,
  .n-modal-portal [data-testid="ad-contact-phone"][data-button-variant="secondary"],
  .n-modal-portal [data-testid="ad-contact-phone"][data-button-variant="secondary"] span,
  .n-modal-portal [data-testid="show-phone"][data-button-variant="secondary"],
  .n-modal-portal [data-testid="show-phone"][data-button-variant="secondary"] span {
    color: #5fd0c6 !important;
    -webkit-text-fill-color: #5fd0c6 !important;
  }

  /* The phone glyph beside "Pokaż" is an <svg> that IS the mint disc (the
     accent is its own background-color) with a fill="currentColor" handset.
     The blanket `#mainContent svg { color: inherit }` handed it the light body
     colour, so the handset washed out to 1.5:1 on its own accent fill. It is
     dark-on-mint natively; restore that and settle the disc on our accent. */
  #mainContent [data-testid="phones-container"] svg {
    background-color: #1fcabf !important;
    color: #07232a !important;
  }

  /* OLX serves logged-out offer pages with a full-bleed "skin"/wallpaper
     takeover ad (a position:absolute iframe sitting BEHIND the content
     column). On the light site the offer column is opaque white so the
     wallpaper only shows in the gutters; our blanket neutraliser made
     the offer column [data-testid="main"] transparent, so the teal ad
     bleeds straight THROUGH the description, chips and meta text and
     guts their contrast. Re-establish a solid dark backdrop on the
     content column (the gallery / cards keep their own surfaces on
     top). */
  #mainContent [data-testid="main"] {
    background-color: #14181d !important;
  }
  /* The offer page's RIGHT rail ([data-testid="aside"]) needs the same
     treatment: the neutraliser strips its light background, so the wallpaper
     takeover ad shows straight through the gaps between its cards. Two of its
     cards are white natively but have no testid of their own — the price/action
     card (first child) and the Zwroty / Pakiet Ochronny block (the sibling
     right after the location card) — so re-elevate them structurally. */
  #mainContent [data-testid="aside"] {
    background-color: #14181d !important;
  }
  #mainContent [data-testid="aside"] > div:first-child,
  #mainContent [data-testid="map-aside-section"] + div {
    background-color: #1c2128 !important;
  }
  /* Same takeover-ad bleed, one level further down the offer page: the two
     recommendation carousels ("Więcej od tego ogłoszeniodawcy" / "Zobacz też")
     paint their own #F2F4F5 band natively (the seller one via an INLINE style
     on its wrapper), and the neutraliser stripped both — so the full-bleed
     wallpaper ad showed straight through the band, behind the section heading
     and in every gap between cards. Both live inside a position:relative
     wrapper that paints after the ad slot, so an opaque background on the
     section itself is enough. */
  #mainContent [data-cy="seller-other-ads"],
  #mainContent [data-testid="ad-recommendations"] {
    background-color: #14181d !important;
  }
  /* …and the page-background bands BETWEEN those blocks. OLX writes them as an
     inline `background:#F2F4F5` on hashed wrappers — the 16px channel between
     the offer column and the right rail, and the 24-32px gaps between sections.
     An inline declaration without !important loses to the neutraliser, so those
     strips went transparent and the wallpaper ad striped the whole page. Match
     them on the serialized inline value (stable: the CSSOM always writes
     `rgb(242, 244, 245)`); the one band that also carries !important is
     #searchmain-container, whose children we re-opaque separately. */
  #mainContent div[style*="background: rgb(242, 244, 245)"] {
    background-color: #14181d !important;
  }
  /* Swiper draws the carousel arrows as ::after glyphs (content:"prev"/"next"
     in its icon font) that inherit the element's colour — OLX sets the literal
     near-black #02282c there, not a token, so both arrows rendered at 1.1:1 on
     the dark band. `*` cannot reach a pseudo-element; colour the button. The
     photo lightbox uses its own arrows and is outside #mainContent. */
  #mainContent .swiper-button-prev,
  #mainContent .swiper-button-next {
    color: #c4cdd6 !important;
  }
  /* "Zobacz wszystkie" (see all of this seller's ads) is a bare <a> in the
     carousel header carrying the same near-black fill token. */
  #mainContent [data-cy="seller-other-ads"] h3 + a {
    color: #5fd0c6 !important;
    -webkit-text-fill-color: #5fd0c6 !important;
  }

  /* Image gallery surrounds (out-specify the blanket neutraliser) */
  #mainContent [data-testid="image-galery-container"],
  #mainContent [data-testid="ad-photo"],
  #mainContent [data-testid="gallery"],
  #mainContent [data-testid="swiper-list"] {
    background-color: #0d1117 !important;
  }

  /* Full-screen photo lightbox. It renders into a `.n-modal-portal` OUTSIDE
     #mainContent, so none of the offer-page text rules reach it. Its dialog is
     the design system's INVERSE surface, and it colours the ad title with the
     `--color-background-primary` token — white on the light site, which we had
     to remap to the page base #14181d. So opening the lightbox printed the
     title in #14181d on a #0d1117 panel: the headline vanished completely, and
     the "Dodane <date>" line under it dropped to 1.9:1. Repaint both directly;
     the token itself must keep pointing at the page base. */
  .n-modal-portal [role="dialog"] [data-testid="offer_title"],
  .n-modal-portal [role="dialog"] [data-testid="offer_title"] h4 {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  .n-modal-portal [role="dialog"] [data-testid="ad-posted-at"] {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  /* The lightbox also duplicates the offer's login-nudge + contact CTAs, but every
     offer-page contact rule is #mainContent-scoped and this dialog lives in the
     .n-modal-portal OUTSIDE #mainContent. So inside the lightbox the login card
     kept its native OLX blue (#1d3c81) and the "Wyślij wiadomość" button its native
     grey secondary fill — both glare on the dark lightbox. Mirror the offer
     treatment for the portal so it matches the main page. */
  .n-modal-portal [data-testid="ad-login-dialog"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* Its prompt copy carries the near-black #14181d fill (designed for the light
     card), so once the card goes dark it drops to ~1:1 — lift it like the offer
     page does for #mainContent [data-testid="prompt-message"]. */
  .n-modal-portal [data-testid="prompt-message"] {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  .n-modal-portal [data-testid="ad-contact-message-button"],
  .n-modal-portal [data-testid="chat-button"] {
    background-color: #1fcabf !important;
    color: #07232a !important;
    border-color: #1fcabf !important;
  }
  .n-modal-portal [data-testid="ad-contact-message-button"] span,
  .n-modal-portal [data-testid="chat-button"] span {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }
  /* The lightbox also injects the ING "Oblicz ratę pożyczki" loan-calculator
     teaser (form.ing_gallery_form) with an INLINE `background: white`, and it
     lives in the .n-modal-portal OUTSIDE #mainContent — so unlike its twin on
     the main offer column (which the neutraliser darkens) it kept a glaring
     white panel on the dark lightbox. The inline white has no !important, so a
     dark surface wins; its blue "Oblicz ratę…" link stays legible on it and the
     2px border is already the hairline via the `*` reset. */
  .n-modal-portal form.ing_gallery_form,
  .n-modal-portal form[class*="ing_gallery"] {
    background-color: #1c2128 !important;
  }

  /* The Romanian sibling of that teaser: the "Calculează rata" entry point under
     the price and the Comperia loan calculator it expands into. Both are marked
     PUBLICITATE but render as inline page content, not an iframe, and both carry
     OLX's near-black #02282c / #002f34 on their own — the CTA label, the
     "Ai nevoie de împrumut?" prompt and the "Rată estimată/lună" line all fell
     dark-on-dark, and the finalize button kept a literal white fill. The
     container's colour is inherited, so lifting it on the shell is enough; the
     green estimate (.comperia_calc_rate) sets its own and stays semantic.
     The teaser's own headline ("Potrzebujesz finansowania?" /
     `-entrypoint-p-main`) carries the same near-black and only renders in the
     mobile shell, so key on the whole entrypoint class family rather than the
     two element suffixes the desktop deploy happens to use. */
  [class*="adv-financing-widget-ad-under-price-entrypoint"] {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  /* `color` only — an inherited `-webkit-text-fill-color` here outranks the
     estimate's own `color` and greys out the green figure. */
  .comperia_calc_adp_de_main {
    color: #c4cdd6 !important;
  }
  /* The monthly estimate is the widget's one semantic colour (#0b8c5e). Keep the
     hue, lift it off the near-black base. */
  #comperia_calc_rate_parent,
  #comperia_calc_rate {
    color: #3fbe86 !important;
    -webkit-text-fill-color: #3fbe86 !important;
  }
  .comperia_calc_finalize_button_main {
    background-color: #30363d !important;
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  .comperia_calc_finalize_button_main span {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }

  /* The CarVertical vehicle-history slot further down the same Romanian offer
     (stable `cvg_*` ids). Its whole copy — headline, pitch, the right column's
     title and the "Partener" label — inherits OLX's near-black #02282C from the
     widget root and fell to ~1.05:1; only the checklist items and the white CTA
     label read. `color` only, so the CTA label's own white still wins. Its CTA
     plate is a literal #022840 navy that the #mainContent neutraliser stripped,
     leaving the label floating with no button shape — give it a lifted navy that
     still reads as the advertiser's blue. The headline sets the near-black on
     itself, so inheritance never reaches it — it needs its own rule. */
  #cvg_king_div { color: #c4cdd6 !important; }
  #cvg_first_line {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  #mainContent .cvg_button_div { background-color: #1e4d7b !important; }

  /* ============================================================
     Login / registration pages (login.olx.<tld> — separate app,
     no design tokens, classic ids: #username / #password / .login-box)
     ============================================================ */
  [data-testid="core-layout"] {
    background-color: #14181d !important;
  }
  /* login.olx.<tld> renders a full-bleed OLX-blue brand splash BEHIND the
     sign-in card: a hashed wrapper with a literal `background:#3A77FF` plus
     lighter concentric ::before / ::after rings. That bright full-viewport
     blue fights the dark theme. The card (.login-box) re-opaques on top one
     level deeper, so flatten just that decorative wrapper (core-layout's
     3rd-level shell) and neutralise its ring pseudos to the dark base. Scoped
     to the login-only core-layout testid, so no other page is affected. */
  [data-testid="core-layout"] > div > div > div {
    background-color: #14181d !important;
  }
  [data-testid="core-layout"] > div > div > div::before,
  [data-testid="core-layout"] > div > div > div::after {
    background-color: transparent !important;
    background-image: none !important;
    box-shadow: none !important;
    border-color: transparent !important;
  }
  .login-box,
  [data-testid="login-form"],
  [data-testid="registration-form"],
  [data-testid="register-form"] {
    background-color: #1c2128 !important;
    border: 1px solid #2d333b !important;
    color: #e6edf3 !important;
  }
  /* At narrow widths the sign-in card gains a 40px "Witamy na OLX!" masthead
     that the desktop layout never renders. It sets OLX's near-black #02282C on
     itself, so the card colour above never reaches it and it vanished into the
     panel at ~1.05:1 — the largest element on the page, invisible. */
  .login-box h1 {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  /* Social sign-in buttons (white pills) -> elevated dark.
     The testid sits on a wrapper; the white surface is the inner button. */
  [data-testid="facebook-button"], [data-testid="facebook-button"] *,
  [data-testid="apple-button"], [data-testid="apple-button"] *,
  [data-testid="google-button"], [data-testid="google-button"] * {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }
  [data-testid="facebook-button"], [data-testid="apple-button"],
  [data-testid="google-button"] { color: #e6edf3 !important; }
  /* The Apple wordmark is a monochrome black SVG (hardcoded #000 / #002F34
     path fills), so it disappears once its pill goes dark. Facebook and Google
     keep their multi-colour marks. */
  [data-testid="apple-button"] svg path { fill: #e6edf3 !important; }
  /* Email + password fields */
  #username, #password,
  [data-testid="login-form"] input,
  [data-testid="register-form"] input {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  /* Tabs (Sign in / Register). The redesigned login app renders the two
     tab <button>s on a literal WHITE pill bar; flip the bar + buttons to
     the elevated dark surface and lift the labels (driven by the same
     near-black -webkit-text-fill token) so the active/inactive tab read. */
  [data-testid="tabs"] { color: #c4cdd6 !important; }
  [data-testid="tabs"] header,
  [data-testid="tabs"] button {
    background-color: #1c2128 !important;
  }
  [data-testid="tabs"] button,
  [data-testid="tabs"] button span {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* Email / password floating labels + the "lub" separator carry the
     near-black token and vanish on dark — force both colour channels.
     The redesigned sign-up form's stable testid is "register-form" (not
     "registration-form"), and its E-mail / Hasło floating labels + the
     consent-checkbox label <span>s render dark-on-dark unless covered, so
     anchor on BOTH testids and reach label spans too. */
  [data-testid="login-form"] label,
  [data-testid="login-form"] label span,
  [data-testid="registration-form"] label,
  [data-testid="registration-form"] label span,
  [data-testid="register-form"] label,
  [data-testid="register-form"] label span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  /* Sign-up password checklist. Each unmet rule ("9 lub więcej znaków", …) is
     an <svg data-testid="false-icon"> whose disc is a literal `fill="white"`
     <rect> with a grey dash across it — invisible on the white card, so only
     the dash reads. On the dark card the disc becomes a row of glaring white
     dots. Sink the disc into the card surface; the dash stays. (The met state
     is a currentColor tick and needs nothing.) */
  svg[data-testid="false-icon"] rect[fill="white"] { fill: #1c2128 !important; }

  /* Show-password eye. The login app is a separate bundle that hardcodes the
     old #406367 secondary colour on the icon instead of reading the token. */
  [data-testid="toggle-password"],
  [data-testid="toggle-password"] svg { color: #9aa6b0 !important; }
  [data-testid="or-separator"],
  [data-testid="or-separator"] span {
    color: #8b949e !important;
    -webkit-text-fill-color: #8b949e !important;
  }
  /* Submit button keeps the OLX accent */
  [data-testid="login-submit-button"],
  [data-testid="register-submit-button"],
  button[type="submit"] {
    background-color: #1fcabf !important;
    color: #07232a !important;
    border-color: #1fcabf !important;
  }
  /* "Nie pamiętasz hasła?" (forgot-password) + the show-password eye are
     un-testid'd <button>s inside the login form carrying the near-black
     token — lift them. The accent submit button is re-asserted just below
     so it keeps its dark-on-teal label. */
  [data-testid="login-form"] button,
  [data-testid="login-form"] button span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  [data-testid="login-form"] [data-testid="login-submit-button"],
  [data-testid="login-form"] [data-testid="login-submit-button"] span {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }
  /* Footer legal blurb under the form (the "Kontynuując…" paragraph) is a
     near-black <p>; lift it while the Regulamin link keeps the teal below. */
  [data-testid="core-layout"] p,
  [data-testid="core-layout"] p span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  [data-testid="terms-conditions-link"],
  a[href*="login"], a[href*="register"],
  [data-testid="link"], a.link { color: #5fd0c6 !important; }
  /* The legal-blurb lift above sets -webkit-text-fill-color on every
     `[data-testid="core-layout"] p span`, and the Regulamin link IS such a span —
     a `color`-only rule cannot beat a text-fill, so the one link in that paragraph
     rendered the same grey as the prose around it. Set both channels, scoped to
     the login shell so the header's own sign-in anchors (also `href*="login"`,
     and deliberately plain white on the dark bar) are not tinted teal. */
  [data-testid="core-layout"] [data-testid="terms-conditions-link"],
  [data-testid="core-layout"] p a {
    color: #5fd0c6 !important;
    -webkit-text-fill-color: #5fd0c6 !important;
  }

  /* ============================================================
     404 / error page ("Ups, mamy problem")

     A completely separate, non-React template: no design tokens, no page
     shell ids, just .c-container / .c-wrapper on a literal cream #FFFBEF
     canvas. It used to carry a [data-cy="404-page"] hook, but the current
     template (served e.g. for an unknown category path on olx.ro) has
     DROPPED that attribute — its DOM is only `body > .c-container >
     .c-wrapper` — so a [data-cy]-scoped rule matched nothing and the page
     shipped as a full-viewport cream sheet whose .c-container__title
     inherited the light body text colour (~1.2:1 on cream, unreadable).
     These four BEM classes are exclusive to this standalone error template
     (the React marketplace uses css-* emotion + page-shell ids, never
     .c-container*), so anchor on the classes directly; keep the legacy
     data-cy selectors in case a variant still ships them.
     ============================================================ */
  [data-cy="404-page"],
  [data-cy="404-page"] .c-wrapper,
  .c-container,
  .c-wrapper {
    background-color: #14181d !important;
  }
  [data-cy="404-page"] .c-container__title,
  .c-container__title {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  [data-cy="404-page"] .c-container__description,
  .c-container__description {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  [data-cy="404-page"] button.button,
  .c-container button.button {
    background-color: #1fcabf !important;
    border-color: #1fcabf !important;
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }

  /* ============================================================
     Breadcrumbs (literal dark-teal text on the listing/offer pages)
     ============================================================ */
  [data-testid="breadcrumbs"], [data-testid="breadcrumbs"] *,
  nav[aria-label*="readcrumb"] a, [class*="breadcrumb"] a {
    color: #9aa6b0 !important;
  }
  [data-testid="breadcrumbs"] a:hover { color: #e6edf3 !important; }

  /* ============================================================
     Generic links + footer
     ============================================================ */
  a { color: #c4cdd6; }
  a:hover { color: #ffffff !important; }

  /* The current OLX footer is a hashed emotion shell with NO <footer>
     element and no "footer" class — it lives under the stable
     #footerContent id. Its link/text colour is driven by the same
     near-black #02282c -webkit-text-fill token, so a plain `color`
     override (or the old footer/[class*=footer] selectors) misses it
     entirely and every footer link renders dark-on-dark. Anchor on
     #footerContent and force BOTH color and -webkit-text-fill. */
  footer,
  [data-testid="footer"],
  [class*="footer"],
  #footerContent {
    background-color: #0d1117 !important;
    color: #9aa6b0 !important;
    border-top: 1px solid #2d333b !important;
  }
  footer a, [data-testid="footer"] a { color: #9aa6b0 !important; }
  footer a:hover { color: #e6edf3 !important; }
  #footerContent a, #footerContent a span,
  #footerContent button, #footerContent button span,
  #footerContent p, #footerContent li, #footerContent span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  #footerContent a:hover, #footerContent a:hover span,
  #footerContent button:hover, #footerContent button:hover span {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  /* OLX marks a hovered footer link by INVERTING it — a solid chip in the
     literal near-black #02282c behind white text. That chip lands at ~1.2:1 on
     the #0d1117 footer, so the hover collapsed to the text lift above. Give the
     chip a surface that actually separates from the bar. */
  #footerContent a:hover,
  #footerContent button:hover {
    background-color: #21262d !important;
  }
  /* The partner strip at the very bottom (OLX.bg / OLX.ro / OLX.ua / OLX.pt /
     Fixly / Otodom / Otomoto / obido) is the ONLY place #footerContent holds
     <svg>s, and OLX desaturates every one of them with `filter: grayscale(1)`.
     Their marks are dark ink drawn for the light #F2F4F5 footer — Otomoto's
     navy ring and obido's unfilled (so pure-black) wordmark all but disappear
     against #0d1117. They carry explicit path fills, so neither `color:inherit`
     nor a `fill` override reaches them; invert the already-grey ink instead. */
  #footerContent a svg { filter: grayscale(1) invert(1) !important; }

  /* ============================================================
     m.olx.<tld> — the MOBILE host

     Phones are redirected to m.olx.<tld>, a separate app shell: its page hangs
     off a <main> under #hydrate-root and carries NONE of the #mainContent /
     #footerContent / #searchmain-container ids that every structural rule above
     anchors on. So the light-shell neutraliser, the card re-opaque and the
     content-text lifts all missed this host completely, and it shipped as white
     ad cards with near-white titles, a white bottom tab bar, a white sticky
     offer header and light content bands. Everything below is anchored on the
     mobile-only testids (or on stable structure under them), and each rule
     either has no desktop counterpart or loses there to the id-scoped rule that
     already covers it — so nothing on the desktop cascade moves.
     ============================================================ */
  /* SPONSOROWANE native ads. OLX injects the same baxter template into the mobile
     listing grid, but this build publishes `baxter-native-listing-olx-<tld>-mobile-…`
     as a CLASS on the ad root where the desktop build makes it an id — so every rule
     in the native-ad block above (all keyed on `[id^="baxter-native-listing"]`, most
     also on `#mainContent`) matched nothing here and the whole sponsored card shipped
     as a literal WHITE panel: the headline sat on it at ~1.7:1 and the condition chip
     vanished. Mirror that block on the class form. It is inert on desktop, where the
     class matches zero elements (verified on the listing and offer pages). */
  [class*="baxter-native-listing"],
  [class*="baxter-native-listing"] * {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  [class*="baxter-native-listing"] [class*="title"] {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  /* The template's own card panel (`…__wrapper`) carries the literal white. It is
     the mobile twin of the desktop ad root above, and its `[data-testid="ad-card"]`
     neighbours sit at the card elevation, so it takes the same one. */
  [class*="baxter-native"][class*="wrapper"] {
    background-color: #1c2128 !important;
  }
  /* …and `…__state` is its condition chip ("Nowe" / "Używane"), a #F2F4F5 pill — the
     mobile twin of the desktop `_spnu`, so it takes the same neutral raised surface. */
  [class*="baxter-native"][class*="__state"] {
    background-color: #21262d !important;
  }
  /* The attribution popup's downward caret is a real-element CSS triangle whose
     left/right borders must stay transparent; the blanket `*` reset paints all four,
     so it renders as a solid grey rectangle. Same repair the desktop arm makes. */
  [class*="baxter-native-listing"] [class*="attribution"],
  [class*="baxter-native-listing"] [class*="popup"],
  [class*="baxter-native-listing"] [class*="tooltip"] {
    background-color: #103c3b !important;
    border-color: #2d333b !important;
  }
  [class*="baxter-native-listing"] [class*="attribution-link"] {
    background-color: #1c2128 !important;
    border-color: #83a4ec !important;
  }
  [class*="baxter-native-listing"] [class*="template__after"] {
    border-top-color: #83a4ec !important;
    border-right-color: transparent !important;
    border-left-color: transparent !important;
  }
  [class*="baxter-native-listing"] [class*="link_close"] svg path {
    stroke: currentColor !important;
  }

  /* Ad card: the body panel is a literal #FFFFFF and the photo box a literal
     #ECEEEF placeholder. The card link holds the photo box first and the badge
     overlay second, so scope the placeholder to the first child (as the desktop
     l-card rule does) and leave the badges transparent. */
  [data-testid="ad-card"] > div { background-color: #1c2128 !important; }
  [data-testid="ad-card"] a > div:first-child { background-color: #21262d !important; }
  /* Motor/property categories give the mobile card a swipeable photo GALLERY instead
     of a single photo, so its placeholder is not the `a > div:first-child` the rule
     above covers: it is the swiper's own `div[type="gallery"]`, still carrying the
     literal #ECEEEF. Every card was a full-width near-white slab until its photo
     painted — and on a lazy-loading list that is most of them. This gallery exists
     only on the mobile host (zero matches on the desktop car listing). */
  [data-testid="ad-card"] div[type="gallery"],
  [data-testid="ad-card"] .swiper-zoom-container {
    background-color: #21262d !important;
  }
  /* A photoless ad falls back to OLX's "no thumbnail" graphic, an SVG served as
     an <img> (no_thumbnail-x.*.svg): an #ECEEEF plate carrying a #D8DFE0 X. As
     an <img> no selector reaches inside it, so it renders as a near-white slab
     the size of a card photo — several per screen on a list view, on both hosts.
     A partial invert lands the plate near the card surface and keeps the X a
     step lighter, so the "no photo" cue survives. Grayscale first: the plate and
     the X are both faintly blue, and inverting a blue grey turns it brown. */
  img[src*="no_thumbnail"] { filter: grayscale(1) invert(0.9) !important; }

  /* Its location / date lines are the dim #406367 that only worked on the white
     panel; the title link keeps the brighter colour set on it directly. */
  [data-testid="ad-card"] p,
  [data-testid="ad-card"] p span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  [data-testid="ad-card"] [data-testid="card-title-link"] {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  [data-testid="ad-card"] [data-testid="ad-price"] {
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
  /* Bottom tab bar (Szukaj / Obserwujesz / Dodaj / Czat / Konto) — a white
     fixed bar; it sits outside <main> so nothing above reached it. */
  [data-testid="bottom-bar-container"],
  [data-testid="bottom-bar-container"] div {
    background-color: #0d1117 !important;
  }
  /* "Przejdź do aplikacji" smart app-install banner — the first 76px of EVERY
     mobile page. Its surface is a literal `background: rgb(255,255,255)` on a
     hashed emotion class, while its close X, title, subtitle and "Otwórz"
     button all read theme tokens we lift to light — so the whole bar rendered
     light-on-white and neither the dismiss control nor the copy was legible.
     It carries no id/testid/stable class of its own (only its children do, and
     CSS cannot select a parent), so anchor it structurally: it is the first
     child, five first-children deep, under the mobile app shell. Verified to
     match exactly this bar on m.olx and NOTHING on the desktop home, listing,
     offer, profile or login shells. Its children already read light. */
  #hydrate-root > div:first-of-type > div:first-child > div:first-child > div:first-child > div:first-child {
    background-color: #0d1117 !important;
  }
  /* Mobile filter form (m.olx.<tld>/searchform/…, opened from the "Filtry"
     chip) and the location picker it opens. A route the theme never covered:
     both screens hang their sticky bar off a literal white <header> carrying
     the ✕ / "Wyczyść" / "Filtry" (and back / "Wybierz lokalizację") controls,
     which inherit our light text — so each panel opened as a white strip with
     invisible labels. The headers have no hook of their own; they are the only
     `main form > div > header` / `main > header` on the site (both zero
     matches on every desktop page type — a bare `main header` would have hit
     the desktop profile's tab bar, hence the child combinator). */
  main form > div > header,
  main > header {
    background-color: #0d1117 !important;
    border-color: #2d333b !important;
  }
  /* This route roots the app at #client-root (not #hydrate-root), so the shell
     rules above miss it and its full-height shell stayed literal white — it
     shows through wherever the panel's content is shorter than the viewport
     (visible behind the location picker's header). */
  #client-root > div { background-color: #14181d !important; }
  /* The picker's geolocation prompt is a light-mint #E9FCFB callout whose copy
     reads our lifted light text, so the whole notice rendered white-on-mint.
     The tint sits on the testid'd node AND its bare wrapper, but the two are
     exactly coincident, so painting the hooked one covers both. */
  [data-testid="listbox"] { background-color: #103c3b !important; }
  /* Each location row's subtitle ("Wszystkie w całym kraju") is the second <p>
     of the row and ships the dim #406367 that only worked on the white sheet —
     1.9:1 here. The row title is the first <p> and stays bright. */
  [data-testid="location-selector"] p + p {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  /* Its section labels ("Sortuj", "Prywatnie czy jako firma") sit in the legacy
     .c-select widget and carry the literal near-black #02282C, not a token, so
     they rendered at ~1.1:1. `.c-select` is one of the few unhashed classes on
     this route and exists nowhere else. */
  .c-select label {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* Its Galeria / Lista / Mozaika view switch marks the two UNSELECTED options
     with .inactive, which reads the disabled foreground token — 4.9:1 on the
     white sheet but only 3.6:1 on ours, under AA for a control that is very
     much clickable. `.inactive` exists on no other page type. */
  main button.inactive span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  /* Account tab (m.olx.<tld>/konto/menu/) — another route with no desktop twin.
     Its "Ustawienia i informacje" section heading and the Pomoc / Regulamin /
     Ustawienia plików cookie rows carry the literal near-black #02282C and the
     sign-in blurb the dim #406367, so the entire lower half of the screen was
     invisible or near-invisible. The heading is the only `main > div > span` on
     the site; the rows and blurb have their own testids. */
  main > div > span,
  [data-testid="user-menu-link"] div {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  [data-testid="user-profile-login-desc"] {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  /* Its "Zaloguj się / Załóż konto" is the screen's data-button-variant="primary"
     and OLX fills it with the same near-black #02282C as the offer "Kup" — a
     1.15:1 slab against our base, so the primary action lost its button shape
     entirely. Same accent treatment as its offer-page counterpart. */
  /* Same near-black primary appears as the Obserwujesz tab's empty-state CTA
     under its own testid, so cover both here. */
  [data-testid="login-btn"],
  [data-testid="observed-log-in-button"] {
    background-color: #1fcabf !important;
    border-color: #1fcabf !important;
  }
  [data-testid="login-btn"],
  [data-testid="login-btn"] span,
  [data-testid="observed-log-in-button"],
  [data-testid="observed-log-in-button"] span {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }

  /* Home: the search band is a literal #F2F4F5 sheet, and the field's ghost
     label is a <p> carrying the dim #406367 that reads ~2:1 once the field
     behind it goes dark. That band is STICKY, so it has to stay opaque — hand it
     the page base rather than flattening it to transparent, or the cards scroll
     straight through the search field. */
  main#homepage > section { background-color: #14181d !important; }
  /* The search submit beside that field is an <svg> that IS the button plate (the fill
     is the SVG's own background-color) with a white fill="currentColor" magnifier. OLX
     paints the plate its near-black #02282c — the strongest control on the white bar,
     but 1.1:1 against our base, so the mobile home's primary action lost its shape and
     only the floating glyph read. Same accent the desktop twin
     ([data-testid="search-submit"]) already gets, with the glyph flipped dark so it
     reads on the mint. `[data-testid="search-bar"]` exists only on the mobile host, and
     this is its one <svg>. */
  [data-testid="search-bar"] svg {
    background-color: #1fcabf !important;
    color: #07232a !important;
  }
  [data-testid="search-bar"] p {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  /* Home category tiles draw each illustration on a #F2F4F5 disc (the desktop
     tiles use coloured artwork instead), so on dark they became a grid of bright
     discs. The illustrations are transparent PNGs, so darkening the disc keeps
     the art. The disc is a stack of three coincident 48x48 divs of which only
     the middle one is round, so the radius has to be re-stated or the square
     holder paints a box over the circle. */
  [data-testid^="cat-button"] div {
    background-color: #21262d !important;
    border-radius: 50% !important;
  }
  /* Offer page. Its content bands are #F2F4F5 <section>s (some direct children,
     some one wrapper deeper), so flatten every section under the shell and then
     put back the two that MUST stay opaque: the fixed top bar (whose white
     backdrop is its own first child, painted behind the back/share/favourite
     controls) and the sticky bottom CTA bar. Both are DIRECT children, so the
     child-combinator rules below out-specify this one. */
  [data-testid="ad-component"] section { background-color: transparent !important; }
  [data-testid="ad-component"] > section:first-of-type > div:first-child {
    background-color: #0d1117 !important;
  }
  [data-testid="ad-component"] > section:last-of-type {
    background-color: #14181d !important;
  }
  /* Offer metadata + the description's "Zobacz więcej" toggle ship the dim
     #406367 / near-black #02282C content colours through -webkit-text-fill. */
  [data-testid="ad-component"] [data-testid="ad-posted-at"],
  [data-testid="ad-component"] [data-testid="member-since"],
  [data-testid="ad-component"] [data-testid="member-since"] span,
  [data-testid="ad-component"] [data-testid="lastSeenBox"],
  [data-testid="ad-component"] [data-testid="lastSeenBox"] span,
  [data-testid="ad-component"] [data-testid="l-card"] p,
  [data-testid="ad-component"] [data-testid="l-card"] p span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  [data-testid="show-more-button-wrapper"] button,
  [data-testid="show-more-button-wrapper"] button span,
  [data-testid="ad-component"] h3 + a {
    color: #5fd0c6 !important;
    -webkit-text-fill-color: #5fd0c6 !important;
  }
  /* Footer meta strip ("ID: …", the report link) — the desktop rule for it is
     #mainContent-scoped. */
  [data-testid="ad-footer-bar-section"],
  [data-testid="ad-footer-bar-section"] span {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  /* The offer's login nudge ("Zaloguj się lub załóż konto na OLX, aby
     skontaktować się…") is a light #EBF1FF panel; the desktop and lightbox
     rules for it are #mainContent / .n-modal-portal scoped, so on the mobile
     host it kept that panel and its (lifted) light copy sat on it at ~1.2:1. */
  [data-testid="ad-component"] [data-testid="ad-login-dialog"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* The seller card's verified-ratings note is a Nexus banner filled from the
     raw #CEDDFF light-blue primitive, and its own utility classes force the
     secondary foreground onto the text — which we lift to #9aa6b0, so the note
     ended up pale grey on pale blue (~2:1). Sink the banner instead of fighting
     the text colour it pins. */
  [data-testid="seller_card"] div[class*="n-banner"] {
    background-color: #1b2436 !important;
  }
  /* In-content loan teaser: its "Finanse:" prefix carries the near-black
     #002F34, and the advertiser's headline the same #3473FE as .creditbox. */
  .link-advert-c,
  .link-advert-c > div {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  .link-advert-c a,
  .link-advert-c a span {
    color: #8ab4ff !important;
    -webkit-text-fill-color: #8ab4ff !important;
  }
  /* The offer's PRIMARY action — "Kup" on a safe-deal listing, "Wyślij
     wiadomość" otherwise — carries OLX's near-black #02282C fill. Every accent
     rule for these CTAs is #mainContent-scoped, so on mobile the single most
     important control on the page rendered as a dead near-black slab. Key on
     the variant the site itself publishes, scoped to the offer shell, so the
     ranking survives whichever CTA OLX promotes to primary. */
  [data-testid="ad-component"] [data-button-variant="primary"],
  [data-testid="ad-component"] [data-testid="go-to-delivery-options"] {
    background-color: #1fcabf !important;
    border-color: #1fcabf !important;
  }
  [data-testid="ad-component"] [data-button-variant="primary"],
  [data-testid="ad-component"] [data-button-variant="primary"] span,
  [data-testid="ad-component"] [data-testid="go-to-delivery-options"],
  [data-testid="ad-component"] [data-testid="go-to-delivery-options"] span {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }
  /* …and the SECONDARY half of that ladder. The mobile shell publishes the call
     CTA under its own hook, [data-testid="ad-contact-call-button"], which none
     of the #mainContent / .n-modal-portal secondary lists carry — so it fell
     through to the generic hairline and rendered as a grey slab whose outline is
     ~1.4:1 on the base, beside a vivid mint primary. Give it the same accent
     outline the desktop rail and the photo lightbox get. */
  [data-testid="ad-component"] [data-testid="ad-contact-call-button"][data-button-variant="secondary"],
  [data-testid="ad-component"] [data-testid="ad-contact-message-button"][data-button-variant="secondary"],
  [data-testid="ad-component"] [data-testid="ad-contact-phone"][data-button-variant="secondary"],
  [data-testid="ad-component"] [data-testid="show-phone"][data-button-variant="secondary"],
  [data-testid="ad-component"] [data-testid="chat-button"][data-button-variant="secondary"] {
    background-color: transparent !important;
    border-color: #5fd0c6 !important;
  }
  [data-testid="ad-component"] [data-testid="ad-contact-call-button"][data-button-variant="secondary"],
  [data-testid="ad-component"] [data-testid="ad-contact-call-button"][data-button-variant="secondary"] span,
  [data-testid="ad-component"] [data-testid="ad-contact-message-button"][data-button-variant="secondary"],
  [data-testid="ad-component"] [data-testid="ad-contact-message-button"][data-button-variant="secondary"] span,
  [data-testid="ad-component"] [data-testid="ad-contact-phone"][data-button-variant="secondary"],
  [data-testid="ad-component"] [data-testid="ad-contact-phone"][data-button-variant="secondary"] span,
  [data-testid="ad-component"] [data-testid="show-phone"][data-button-variant="secondary"],
  [data-testid="ad-component"] [data-testid="show-phone"][data-button-variant="secondary"] span,
  [data-testid="ad-component"] [data-testid="chat-button"][data-button-variant="secondary"],
  [data-testid="ad-component"] [data-testid="chat-button"][data-button-variant="secondary"] span {
    color: #5fd0c6 !important;
    -webkit-text-fill-color: #5fd0c6 !important;
  }
  /* The gallery's favourite disc is a solid #FF5636 circle whose 2px border is
     the same orange, so it reads as one shape. The blanket border reset painted
     that ring the neutral hairline and cut a grey outline into the brand
     control; give the border back its fill colour. */
  [data-testid="photos-fav-icon"] div { border-color: #ff5636 !important; }

  /* The vehicle-history (autoDNA) block only exists in the mobile offer shell,
     under the description section, and its body copy — "Partner:", the pitch
     line and both bullets — is the near-black #02282C built for the white card.
     Its heading and CTA read a token we remap, so only these NexusText
     paragraphs were stranded at ~1.05:1. They are the section's only
     NexusText paragraphs; the ad description itself is not one. */
  [data-testid="ad-description-section"] p[data-nx-name="NexusText"] {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }

  /* ============================================================
     Nexus "inverted" states — hover, and the dropdown's current row

     OLX's Nexus components express their strongest state by INVERTING:
     `background: var(--colorsForegroundPrimary)` paired with
     `color: var(--colorsForegroundOnDark)`. Here that foreground token is the
     near-white body text, so every such state painted a blank white slab —
     subcategory chips, the seller-type tabs, the currency toggle, the "show
     all" expander, and the open category dropdown's CURRENT row (which reads
     the token at rest, not on hover, and so rendered white-on-white).

     Fix the CONTRACT, not the emotion hashes: those rotate every deploy, so
     flip BOTH halves of the pairing for the duration of the state and let the
     site's own rule compute the dark inversion. The flip is inert wherever the
     site does not read the token as a surface, so the anchor list can be
     widened safely. The trailing `*` rules restore the token's TEXT role for
     descendants, which would otherwise inherit the surface value and vanish.
     ============================================================ */
  #mainContent [data-testid="category-count-links"] a:hover,
  #mainContent [data-testid="top-listing-filters"] button:hover,
  #mainContent [data-testid="currency-item"]:hover,
  #mainContent [data-testid="ad-card-title"] h4:hover,
  #listing-filters li > span:hover,
  [data-testid="category-dropdown-list"] [role="menuitem"]:hover {
    --colorsForegroundPrimary: #2d333b;
    --color-foreground-primary: #2d333b;
    --colorsForegroundOnDark: #e6edf3;
    --color-foreground-on-dark: #e6edf3;
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  #mainContent [data-testid="category-count-links"] a:hover *,
  #mainContent [data-testid="top-listing-filters"] button:hover *,
  #mainContent [data-testid="currency-item"]:hover *,
  #mainContent [data-testid="ad-card-title"] h4:hover *,
  #listing-filters li > span:hover *,
  [data-testid="category-dropdown-list"] [role="menuitem"]:hover * {
    --colorsForegroundPrimary: #e6edf3;
    --color-foreground-primary: #e6edf3;
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }

  /* Category dropdown rows. The current row is the only one the site paints at
     rest, and nothing but the emotion hash distinguishes it — so scope the
     surface role of the token to every row and let the site pick. Accent-subtle
     for "current" keeps it apart from the neutral hover step above. */
  [data-testid="category-dropdown-list"] [role="menuitem"] {
    --colorsForegroundPrimary: #103c3b;
    --color-foreground-primary: #103c3b;
    --colorsForegroundOnDark: #7ee0d6;
    --color-foreground-on-dark: #7ee0d6;
    color: #e6edf3 !important;
  }
  [data-testid="category-dropdown-list"] [role="menuitem"] * {
    --colorsForegroundPrimary: #e6edf3;
    --color-foreground-primary: #e6edf3;
  }

  /* Same contract via Tailwind, where the surface lands on a CHILD
     (`hover:[&>p]:bg-foreground-primary`) — the homepage category tiles. The
     paired label utility is `text-background-primary!`, a LAYERED !important
     that no unlayered override can beat, so redefine the variable it resolves
     instead. Keyed on the utility name, which is the token name. */
  [data-testid="home-categories-menu"] a:hover > p,
  [data-testid="home-categories-menu-row"] a:hover > p,
  [class*="bg-foreground-primary"]:hover > p,
  [class*="bg-foreground-primary"]:hover > span {
    --color-foreground-primary: #2d333b;
    --colorsForegroundPrimary: #2d333b;
    --color-background-primary: #e6edf3;
    background-color: #2d333b !important;
  }

  /* ============================================================
     OneTrust consent (#onetrust-banner-sdk / #onetrust-pc-sdk)

     OLX's CMP mounts as a direct child of <body>, outside every page-shell id,
     so nothing above reaches it: the banner every first-time visitor sees, and
     the preference centre behind the footer's "Ustawienia plików cookie" link,
     both shipped as literal white sheets. Its `ot-*` ids and class names are
     the SDK's own and are stable across builds.

     Two things beyond the surface. Its copy is the near-black #002F34, so it
     has to be lifted along with the panel. And all of its filled actions —
     accept, reject, save — are that SAME near-black with white labels, i.e.
     ~1.1:1 once the sheet goes dark, while the "set preferences" secondary is
     a literal WHITE fill that would become a white slab; put the filled tier
     on the theme accent and the secondary on an accent outline.
     ============================================================ */
  #onetrust-banner-sdk,
  #onetrust-pc-sdk,
  #onetrust-pc-sdk .ot-pc-header,
  #onetrust-pc-sdk #ot-pc-content,
  #onetrust-pc-sdk .ot-pc-footer,
  #onetrust-pc-sdk .ot-accordion-layout,
  #onetrust-pc-sdk .ot-cat-item,
  #onetrust-pc-sdk #ot-pc-lst,
  #onetrust-pc-sdk .ot-vlst-cntr,
  #onetrust-pc-sdk #vendor-list-content,
  #onetrust-pc-sdk .ot-search-cntr,
  #onetrust-pc-sdk input[type="text"],
  #onetrust-pc-sdk input[type="search"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* An expanded category's purpose text drops into a #F8F8F8 sub-panel that
     only exists once the accordion is opened, so it is invisible to any
     load-time scan. It nests inside the card, so it takes the page base. */
  #onetrust-pc-sdk .ot-acc-grpcntr,
  #onetrust-pc-sdk .ot-acc-txt,
  #onetrust-pc-sdk .ot-acc-hdr,
  #onetrust-pc-sdk #ot-sel-blk,
  #onetrust-pc-sdk .ot-vlst-cntr .ot-ven-hdr,
  #onetrust-pc-sdk .ot-subgrp-cntr {
    background-color: #14181d !important;
    border-color: #2d333b !important;
  }
  #onetrust-banner-sdk h2,
  #onetrust-banner-sdk h3,
  #onetrust-banner-sdk h4,
  #onetrust-pc-sdk h2,
  #onetrust-pc-sdk h3,
  #onetrust-pc-sdk h4,
  #onetrust-pc-sdk h5,
  #onetrust-pc-sdk h6 {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  #onetrust-banner-sdk p,
  #onetrust-banner-sdk div,
  #onetrust-banner-sdk span,
  #onetrust-banner-sdk li,
  #onetrust-banner-sdk button,
  #onetrust-pc-sdk p,
  #onetrust-pc-sdk div,
  #onetrust-pc-sdk span,
  #onetrust-pc-sdk li,
  #onetrust-pc-sdk button,
  #onetrust-pc-sdk input {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  #onetrust-banner-sdk a,
  #onetrust-banner-sdk .ot-link-btn,
  #onetrust-pc-sdk a,
  #onetrust-pc-sdk .ot-link-btn {
    color: #5fd0c6 !important;
    -webkit-text-fill-color: #5fd0c6 !important;
  }
  /* OneTrust boxes the cookie-policy link in a 1px pure-black `outline` — an
     outline is not a border, so the `*` reset never reaches it and it sat at
     ~1.15:1. It is the one link the banner deliberately singles out. */
  #onetrust-banner-sdk .ot-cookie-policy-link,
  #onetrust-banner-sdk .ot-imprint-link {
    outline-color: #5fd0c6 !important;
  }
  /* "Zawsze aktywne" is the always-on status of the strictly-necessary
     category — a semantic blue (#3860BE), not body copy. Keep the hue. */
  #onetrust-pc-sdk .ot-always-active {
    color: #8ab4ff !important;
    -webkit-text-fill-color: #8ab4ff !important;
  }
  #onetrust-banner-sdk #onetrust-accept-btn-handler,
  #onetrust-banner-sdk #onetrust-reject-all-handler,
  #onetrust-pc-sdk #accept-recommended-btn-handler,
  #onetrust-pc-sdk .save-preference-btn-handler,
  #onetrust-pc-sdk .ot-pc-refuse-all-handler {
    background-color: #1fcabf !important;
    border-color: #1fcabf !important;
  }
  #onetrust-banner-sdk #onetrust-accept-btn-handler,
  #onetrust-banner-sdk #onetrust-reject-all-handler,
  #onetrust-pc-sdk #accept-recommended-btn-handler,
  #onetrust-pc-sdk .save-preference-btn-handler,
  #onetrust-pc-sdk .ot-pc-refuse-all-handler {
    color: #07232a !important;
    -webkit-text-fill-color: #07232a !important;
  }
  #onetrust-banner-sdk #onetrust-pc-btn-handler {
    background-color: transparent !important;
    border-color: #5fd0c6 !important;
    color: #5fd0c6 !important;
    -webkit-text-fill-color: #5fd0c6 !important;
  }
  /* The +/- accordion expander is drawn as two coloured bars, not a glyph. */
  #onetrust-pc-sdk .ot-plus-minus span { background-color: #c4cdd6 !important; }
  /* The close ✕ is a dark background-image SVG and both OneTrust wordmarks are
     black rasters, so they need inverting. Invert the logo <img> only: the
     filter is inherited-in-effect by nesting, and inverting the .ot-pc-logo
     wrapper as well would invert the mark twice, back to black. */
  #onetrust-pc-sdk #close-pc-btn-handler,
  #onetrust-pc-sdk .ot-pc-logo img,
  #onetrust-pc-sdk .ot-pc-footer-logo img {
    filter: invert(1) !important;
  }
  /* OneTrust boxes that ✕ in a 1px black `outline` (not a border, so the `*`
     reset never reaches it), and the filter above inverts the element's own
     outline too — hence the pre-inverted value: this paints as #2d333b. */
  #onetrust-pc-sdk #close-pc-btn-handler { outline-color: #d2ccc4 !important; }

  /* ============================================================
     Laquesis in-product survey (#laq-survey-root)

     OLX's own feedback widget ("Cześć! Czy możemy zająć Ci minutę?" →
     NPS bar → free text → thank-you). It mounts as a direct child of
     <body>, so NOTHING scoped to #mainContent / #hydrate-root / the
     mobile shell reaches it, and it is frequency-capped by the
     `lqstatus` cookie — clear that cookie and call
     window.laquesisShowSurvey(<id from localStorage.laquesissu>) to
     make it render on demand.

     Its stylesheet (ninja.data.olxcdn.com/laquesis-survey-cee.css) is
     entirely token-driven off --surveys-* declared on `.laq-survey`,
     and its own rules are long descendant chains, so redefining those
     tokens one specificity step up is the whole fix. Two exceptions
     below need literal declarations because the blanket
     `* { border-color }` reset carries !important and beats them.
     ============================================================ */
  #laq-survey-root .laq-survey {
    --surveys-bg-color: #1c2128;
    --surveys-font-color: #e6edf3;
    --surveys-hint-color: #9aa6b0;
    --surveys-border-color: #2d333b;
    --surveys-input-border-color: #2d333b;
    --surveys-input-bg-color: #14181d;
    --surveys-hover-color: #21262d;
    --surveys-list-item-active-bg-color: #103c3b;
    --surveys-item-inactive-text-color: #6b7681;
    --surveys-item-active-bg-color: #1fcabf;
    --surveys-item-active-text-color: #07232a;
    --surveys-mask-color: rgba(0, 0, 0, 0.6);
    /* The NPS bar keeps its red→green gradient: it IS the answer scale.
       Both of these default to tokens flipped light above, so pin them
       back to their native values or the 0-10 digits and the selected
       marker land light-on-pastel. */
    --surveys-rating-text-color: #07232a;
    --surveys-rating-selected-bg-color: #ffffff;
    /* Welcome popup CTAs: the accept button is OLX's near-black primary
       and the decline its outline twin — same ladder as the offer-page
       contact CTAs, so give them the same accent/secondary pair. */
    --surveys-popup-action-accept-bg-color: #1fcabf;
    --surveys-popup-action-accept-text-color: #07232a;
    --surveys-popup-action-accept-border-color: #1fcabf;
    --surveys-popup-action-decline-bg-color: transparent;
    --surveys-popup-action-decline-text-color: #5fd0c6;
    --surveys-popup-action-decline-border-color: #5fd0c6;
  }
  #laq-survey-root .laq-layout__actions--accept {
    border-color: #1fcabf !important;
  }
  #laq-survey-root .laq-layout__actions--decline {
    border-color: #5fd0c6 !important;
  }
  /* The radio/checkbox rings are 2px borders the reset flattens to the
     #2d333b hairline (1.4:1 on the panel), and the checked ring is the
     only thing separating a picked answer from an unpicked one. */
  #laq-survey-root input[type="radio"],
  #laq-survey-root input[type="checkbox"] {
    border-color: #6b7681 !important;
  }
  #laq-survey-root input[type="radio"]:checked,
  #laq-survey-root input[type="checkbox"]:checked {
    border-color: #1fcabf !important;
  }
  /* The free-text answer box: the generic textarea/input fill further up is
     also !important and ties the --surveys-input-bg-color token, so the field
     landed flush with the panel it sits on. Sink it one step. */
  #laq-survey-root textarea,
  #laq-survey-root input[type="text"] {
    background-color: #14181d !important;
  }

  /* ============================================================
     SurveyMonkey website collector (.smcx-widget)

     A second survey overlay alongside Laquesis, wired per category
     (olx.ro's /autoturisme/ listing runs one). Its markup is a direct
     child of <body>, so nothing scoped to a page shell reaches it, and
     its two stylesheets arrive as inline `<style class="smcx-style">`
     blocks written by a same-origin sandbox iframe — the widget itself
     is host-document DOM, so it IS reachable.

     Shown to a `sample_rate` share of visits (10% here); force it with
     document.getElementById('smcx_frame')
       .contentWindow.SMCX.env.app.insertWidgetView()

     The chrome ring and the primary CTA carry the campaign's own two
     colours, configured server-side per collector, so they are neither
     hex-stable nor ours to flatten — only the content panel and the
     inks sitting on it are re-pointed. `.smcx-widget` is the root class
     every layout of the widget carries, so it is the scope hook. */
  .smcx-widget {
    color: #e6edf3 !important;
  }
  .smcx-widget .smcx-modal-content {
    background-color: #1c2128 !important;
  }
  .smcx-widget .smcx-modal-h1 {
    color: #e6edf3 !important;
  }
  .smcx-widget .smcx-modal-p {
    color: #9aa6b0 !important;
  }
  /* The decline action is a light-grey fill with black ink — the vendor's
     lesser tier next to the campaign-coloured primary. It needs a fill
     light enough to stay a visible button on the panel it sits on. */
  .smcx-widget .smcx-btn-secondary {
    background-color: #30363d !important;
    color: #e6edf3 !important;
  }

  /* The mobile search results serve an occasional Baxter interstitial whose
     320x480 plate mounts at body level, outside every page-shell id, and
     carries a literal white behind the creative. */
  #baxter-interstitial-modal-content {
    background-color: #14181d !important;
  }

  /* ============================================================
     Directory pages — /sitemap/, /sitemap/regions/, /popularne/

     Three link-index routes that share the marketplace shell but none
     of its cards. Their anchors and section bars carry the literal
     near-black #02282C on a hashed emotion class, so the un-!important
     base `a` rule loses and every entry rendered dark-on-dark; the
     `<header>`/`<p>` bars keep a literal #FFFFFF / #F2F4F5 that the
     blanket neutraliser misses (it only reaches div/section/article/ul).

     Anchor on the Nexus data-nx-name contract and the page testids —
     the emotion hashes rotate every deploy. m.olx.<tld> serves the same
     three routes off its own shell (no #mainContent), so these carry no
     shell id; every hook here is either route-unique or already lands on
     the value it would compute anyway. The structural selectors ARE
     shell-scoped: they name a depth, so they only make sense per shell.
     ============================================================ */
  header[data-nx-name="PageHeader"] {
    background-color: transparent !important;
  }
  h1[data-nx-name="H2"] { color: #e6edf3 !important; }
  [data-testid="top-cities"] > p,
  a[data-testid="most-searched-header-link"] {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }
  [data-nx-name="P5"] > a { color: #c4cdd6 !important; }
  /* Category heading (/sitemap/) and voivodeship link (/sitemap/regions/)
     on the desktop shell; the mobile shell wraps the same two in a Nexus
     accordion head and a P3 header instead. */
  #mainContent > div > div > a { color: #e6edf3 !important; }
  #mainContent > div > div > div > p > a,
  main > div > div > div > a,
  header[data-nx-name="P3"] > a,
  p[data-nx-name="P4"] > a,
  .n-accordionitem-header__content a { color: #c4cdd6 !important; }
  /* The mobile region map bands each voivodeship in the accent-subtle mint
     the light page uses for a section rule. */
  header[data-nx-name="P3"] { background-color: #1c2128 !important; }
  /* The per-category ad counts. Label2 is the design system's dimmest
     text role; everywhere else in the theme it lands on #9aa6b0, but on
     these pages it keeps its own literal #406367 (2.6:1 on the base). */
  [data-nx-name="Label2"] { color: #9aa6b0 !important; }

  /* ============================================================
     Jobs app (/pracodawcy/…, /firma/…)

     A separate app styled with per-deploy atomic `jpx-*` classes over
     Base Web primitives, mounted under two roots: the employers
     directory and the employer profile. Nothing in the marketplace
     shell reaches either — on the desktop shell they inherit the dark
     page and their near-black #02282C ink goes invisible; on
     m.olx.<tld> they ship as full white pages inside the dark theme.
     The `jpx-*` classes rotate every deploy, so the only usable hooks
     are the two roots, the app's own testids, `data-baseweb` and the
     ARIA state attributes. Its page column is the only
     `main[data-nx-name="Page"] > div`.

     The directory goes flat under lifted ink; the profile keeps its
     sections as cards, because they are the only thing separating one
     block of the profile from the next.
     ============================================================ */
  main[data-nx-name="Page"] > div,
  [data-testid="company-profile-employers-root"] div,
  [data-testid="company-profile-employers-root"] section,
  [data-testid="company-profile-employers-root"] ul,
  [data-testid="company-profile-employers-root"] li,
  [data-testid="company-profile-employers-root"] header,
  [data-testid="company-profile-employers-root"] footer,
  [data-testid="company-profile-employers-root"] nav,
  [data-testid="company-profile-public-view-root"] div,
  [data-testid="company-profile-public-view-root"] ul,
  [data-testid="company-profile-public-view-root"] li,
  [data-testid="company-profile-public-view-root"] aside,
  [data-testid="company-profile-public-view-root"] header,
  [data-testid="company-profile-public-view-root"] footer,
  [data-testid="company-profile-public-view-root"] nav {
    background-color: transparent !important;
  }
  /* The hydration skeleton is the app's only bare-`testid` node, and its
     shimmer is a near-white gradient background-IMAGE, which the surface
     flatten above does not touch. Keep the stop order: the sweep animates
     background-position across a 400%-wide gradient. */
  [data-testid="company-profile-employers-root"] div[testid="loader"],
  [data-testid="company-profile-public-view-root"] div[testid="loader"] {
    background-image: linear-gradient(90deg, #21262d, #21262d, #21262d, #2d333b, #21262d, #21262d) !important;
  }
  /* Every direct child of a skeleton block is a line placeholder, and each
     carries its own shimmer a step lighter than the block it sits on. */
  [data-testid="company-profile-employers-root"] div[testid="loader"] > div,
  [data-testid="company-profile-public-view-root"] div[testid="loader"] > div {
    background-image: linear-gradient(90deg, #2d333b, #2d333b, #2d333b, #3a424c, #2d333b, #2d333b) !important;
  }
  [data-testid="company-profile-employers-root"] article,
  [data-testid="company-profile-employers-root"] [data-testid="employer-card"],
  [data-testid="company-profile-public-view-root"] article,
  [data-testid="company-profile-public-view-root"] section[data-testid="section"],
  [data-testid="company-profile-public-view-root"] section[data-testid="recruitment-section"],
  [data-testid="company-profile-public-view-root"] aside[data-testid="feedback-widget"] {
    background-color: #1c2128 !important;
  }
  /* Panels nested one level inside a profile card — the info rows, the
     benefit tiles and the leave-your-CV promo, the last being the only
     `section` on the profile with no testid of its own. */
  [data-testid="company-profile-public-view-root"] section:not([data-testid]) > div,
  [data-testid="additional-info-content"] aside,
  [data-testid="benefits-content"] > li {
    background-color: #21262d !important;
  }
  /* Base Web mounts every dropdown in a popover portal outside both
     roots, so nothing root-scoped reaches it. */
  [data-baseweb="popover"] {
    background-color: #1c2128 !important;
  }
  /* Employer marks are dark-ink brand logos that only read on a white
     plate; the plate is an unhookable wrapper div, so put the white on
     the image itself. */
  [data-testid="company-profile-employers-root"] img[data-testid="logo"],
  [data-testid="company-profile-employers-root"] [data-testid="default-logo"],
  [data-testid="company-profile-public-view-root"] img[data-testid="logo"],
  [data-testid="company-profile-public-view-root"] [data-testid="default-logo"] {
    background-color: #ffffff !important;
  }
  [data-testid="company-profile-employers-root"] h1,
  [data-testid="company-profile-employers-root"] h2,
  [data-testid="company-profile-employers-root"] h3,
  [data-testid="company-profile-public-view-root"] h1,
  [data-testid="company-profile-public-view-root"] h2,
  [data-testid="company-profile-public-view-root"] h3 {
    color: #e6edf3 !important;
  }
  /* `disabled` is the app's only marker for a spent pagination arrow —
     it carries the dim ink and nothing else — so the lift has to stop
     short of it. */
  [data-testid="company-profile-employers-root"] a,
  [data-testid="company-profile-employers-root"] a span,
  [data-testid="company-profile-employers-root"] a strong,
  [data-testid="company-profile-employers-root"] span,
  [data-testid="company-profile-employers-root"] strong,
  [data-testid="company-profile-employers-root"] div,
  [data-testid="company-profile-employers-root"] button:not([disabled]),
  [data-testid="company-profile-employers-root"] button span,
  [data-testid="company-profile-public-view-root"] a,
  [data-testid="company-profile-public-view-root"] a span,
  [data-testid="company-profile-public-view-root"] a strong,
  [data-testid="company-profile-public-view-root"] span,
  [data-testid="company-profile-public-view-root"] strong,
  [data-testid="company-profile-public-view-root"] p,
  [data-testid="company-profile-public-view-root"] div,
  [data-testid="company-profile-public-view-root"] button:not([disabled]),
  [data-testid="company-profile-public-view-root"] button span {
    color: #c4cdd6 !important;
  }
  /* The desktop shell's `#mainContent ul li a` ink lands on the card link —
     it out-specifies the lift above and carries a -webkit-text-fill-color,
     which INHERITS down and paints every tier of the card one flat tone. The
     id is what gives these the specificity to beat it, and m.olx has no
     #mainContent, so it is also what keeps them off the mobile shell.
     The exclusions matter: an id in the selector outranks every button and
     tier rule in this section, so the ones whose ink is their whole point
     have to be kept out of the match rather than re-asserted. */
  #mainContent [data-testid="company-profile-employers-root"] a:not([data-baseweb="button"]),
  #mainContent [data-testid="company-profile-employers-root"] a:not([data-baseweb="button"]) span:not([data-testid]),
  #mainContent [data-testid="company-profile-public-view-root"] a:not([data-baseweb="button"]),
  #mainContent [data-testid="company-profile-public-view-root"] a:not([data-baseweb="button"]) span:not([data-testid]) {
    color: #c4cdd6 !important;
  }
  #mainContent [data-testid="company-profile-employers-root"] *,
  #mainContent [data-testid="company-profile-public-view-root"] * {
    -webkit-text-fill-color: currentColor !important;
  }
  /* Every glyph in the app is a Base Web icon whose paths are
     `fill="currentColor"`, so the ink of the host control is the whole
     control — inheriting keeps a muted link's icon muted instead of
     flattening every icon to one tone. */
  [data-testid="company-profile-employers-root"] svg[data-baseweb="icon"],
  [data-testid="company-profile-public-view-root"] svg[data-baseweb="icon"] {
    color: inherit !important;
  }
  /* The two dimmer ink tiers the blanket lift above would otherwise
     flatten into the body tone. */
  [data-testid="company-profile-public-view-root"] [data-testid="member-since"],
  [data-testid="company-profile-public-view-root"] [data-testid="position-card-date"] {
    color: #9aa6b0 !important;
  }
  /* Pagination marks the current page with a ring, not a fill, and the
     blanket border reset flattens it into the hairline tone. */
  [data-testid="company-profile-employers-root"] nav button[aria-current="true"],
  [data-testid="company-profile-public-view-root"] nav button[aria-current="true"] {
    border-color: #5fd0c6 !important;
    color: #e6edf3 !important;
  }
  /* The selected recruitment tab is marked by ink weight plus a 3px
     sliding bar the tab list keeps as a `presentation` child — the
     surface flatten above would leave the two tabs indistinguishable. */
  [data-testid="company-profile-public-view-root"] [data-testid="recruitment-section"] [aria-selected="true"] {
    color: #e6edf3 !important;
  }
  [data-testid="company-profile-public-view-root"] [role="tablist"] > [role="presentation"] {
    background-color: #5fd0c6 !important;
  }
  /* Its search CTA is the same near-black #02282C primary the offer-page
     contact buttons use — a 1.2:1 slab here — so it takes the same accent. */
  [data-testid="employers-searchbox"] button {
    background-color: #1fcabf !important;
    border-color: #1fcabf !important;
  }
  /* Its label and glyph sit in wrapper elements the blanket lift above
     also matches, and on the accent fill they need the inverse ink. */
  [data-testid="employers-searchbox"] button,
  [data-testid="employers-searchbox"] button div,
  [data-testid="employers-searchbox"] button span,
  [data-testid="employers-searchbox"] button svg {
    color: #07232a !important;
  }
  /* Same ladder on the profile: the leave-your-CV link is the app's only
     filled primary, an anchor-button one level inside the promo panel —
     every other anchor-button in the app is the outline kind. */
  [data-testid="company-profile-public-view-root"] section:not([data-testid]) > div > a[data-baseweb="button"] {
    background-color: #1fcabf !important;
    color: #07232a !important;
    border-color: #1fcabf !important;
  }
  [data-testid="company-profile-public-view-root"] section:not([data-testid]) > div > a[data-baseweb="button"] span {
    color: #07232a !important;
  }
  /* …and the outline kind, whose ring is an inset box-shadow rather than
     a border, so no border reset reaches it. */
  [data-testid="company-profile-employers-root"] section > a[data-baseweb="button"],
  [data-testid="feedback-widget"] button {
    box-shadow: inset 0 0 0 2px #5fd0c6 !important;
    color: #5fd0c6 !important;
  }
  [data-testid="company-profile-employers-root"] section > a[data-baseweb="button"] span,
  [data-testid="feedback-widget"] button span {
    color: #5fd0c6 !important;
  }
  /* Its carousel arrows are a white disc drawn for the white page, and
     `disabled` is the only thing separating an available arrow from a
     spent one — so the fill has to stay off the disabled twin. */
  [data-testid="control-button-prev"]:not([disabled]),
  [data-testid="control-button-next"]:not([disabled]) {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }
  /* The dot strip encodes the current slide by DARKENING it — the
     current dot is a 30%-alpha near-black and the rest mid-grey, so on
     a dark page the indicator inverted and the current slide read as
     the only missing dot. */
  [data-testid="dot-button"] { background-color: #4a525c !important; }
  [data-testid="dot-button"][aria-current="true"] {
    background-color: #e6edf3 !important;
  }

  /* ============================================================
     Legacy landing template (#innerLayout)

     OLX's pre-React pages — "Jak działa OLX", the promotion-package
     pricing page — still ship the old Tablica shell: no design tokens,
     no #mainContent, plain BEM classes. Their content bands are
     literal white/mint/periwinkle and every heading, paragraph and
     footer link is the near-black #002F34 drawn for them.

     Flatten every light band first, THEN lift the ink: lifting alone
     leaves white-on-white inside the cards that stay light. The footer
     needs the id in the selector because its own `.link.gray` rule is
     !important and out-specifies the generic `footer a`.
     ============================================================ */
  #innerLayout .lp-box,
  #innerLayout .lp-bundles-intro__content,
  #innerLayout .lp-bundles-options-intro__box,
  #innerLayout .bundle-item,
  #innerLayout .bundles-about,
  #innerLayout .bundles-about__img,
  #innerLayout .container > ul > li {
    background-color: transparent !important;
  }
  #innerLayout h1, #innerLayout h2, #innerLayout h3,
  #innerLayout h4, #innerLayout h5, #innerLayout h6 {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  #innerLayout p, #innerLayout li, #innerLayout dd, #innerLayout dt {
    color: #c4cdd6 !important;
    -webkit-text-fill-color: #c4cdd6 !important;
  }
  /* The template's nav bar is an <li> list, so the content lift above dims
     the site's own white chrome by a step. Hand it back. */
  #header-container li,
  #header-container a,
  #header-container span {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }
  /* The package tables mark a feature the tier does NOT include with a
     muted row and a muted tick — the ink IS the state, so the lift above
     has to stop short of it. */
  #innerLayout li.disabled,
  #innerLayout li.disabled * {
    color: #6b7681 !important;
    -webkit-text-fill-color: #6b7681 !important;
  }
  /* Same near-black-primary ladder as the React CTAs: on white #002F34 IS
     the strongest button, on our base it is a 1.2:1 slab. The secondary is
     its ghost twin (text + hairline only), so it only needs the ink. */
  #innerLayout .olx-button--primary,
  #innerLayout .postnewlink,
  #innerLayout .login-button:not(.login-button--facebook) {
    background-color: #1fcabf !important;
    color: #07232a !important;
    border-color: #1fcabf !important;
  }
  #innerLayout .olx-button--secondary {
    color: #5fd0c6 !important;
    border-color: #5fd0c6 !important;
  }
  #innerLayout .login-button--facebook {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }
  #innerLayout footer a,
  #innerLayout footer a span,
  #innerLayout footer span,
  #innerLayout footer li,
  #innerLayout footer p {
    color: #9aa6b0 !important;
    -webkit-text-fill-color: #9aa6b0 !important;
  }
  #innerLayout footer a:hover,
  #innerLayout footer a:hover span {
    color: #e6edf3 !important;
    -webkit-text-fill-color: #e6edf3 !important;
  }

  /* ============================================================
     WordPress marketing sites — hand the surface back

     `domain("olx.<tld>")` also matches biznes./blog./ad.olx.<tld> and
     the /zawodowo/ and /lp/* landings, none of which are the
     marketplace: they are WordPress + Elementor brochures with their
     own complete light design. The base paint turned their <body> dark
     while their own sections stayed white, so mint cards rendered
     near-white heading on near-white card and the copyright line
     vanished. WordPress always stamps its theme and template slugs on
     <body>, and nothing on the marketplace or the legacy shell carries
     either — restore the light page rather than half-theme it.
     ============================================================ */
  body[class*="wp-theme-"],
  body[class*="page-template-"] {
    background-color: #ffffff !important;
    color: #1a1a1a !important;
    min-height: 100vh;
  }
  body[class*="wp-theme-"] a:hover,
  body[class*="page-template-"] a:hover { color: inherit !important; }
  /* `main` is one of the marketplace shell anchors the base fill paints, and
     these templates use the tag for their whole content column. */
  body[class*="wp-theme-"] main,
  body[class*="wp-theme-"] main > header,
  body[class*="page-template-"] main,
  body[class*="page-template-"] main > header {
    background-color: transparent !important;
  }
  /* The footer paint reaches these pages through `[class*="footer"]`, which
     Elementor's own `elementor-location-footer` wrapper satisfies. */
  body[class*="wp-theme-"] footer,
  body[class*="wp-theme-"] [class*="footer"],
  body[class*="page-template-"] footer,
  body[class*="page-template-"] [class*="footer"] {
    background-color: transparent !important;
    color: inherit !important;
    border-top: 0 !important;
  }
  body[class*="wp-theme-"] footer a,
  body[class*="wp-theme-"] [class*="footer"] a,
  body[class*="page-template-"] footer a,
  body[class*="page-template-"] [class*="footer"] a { color: inherit !important; }

  /* ============================================================
     Scrollbar polish
     ============================================================ */
  ::-webkit-scrollbar { width: 12px; height: 12px; }
  ::-webkit-scrollbar-track { background: #0d1117; }
  ::-webkit-scrollbar-thumb { background: #2d333b; border-radius: 6px; }
  ::-webkit-scrollbar-thumb:hover { background: #3a424c; }
}
